-- 티라미수 케익 챌린지 (a8txvsut / 티라미수-케익-챌린지)
update public.memes set
  description = '인디밴드 위아더나잇의 곡 ''티라미수 케익''에 맞춰, 두 팔을 머리 위로 올려 동그라미를 만들었다가 내리며 다리를 가볍게 흔드는 춤을 따라 추는 챌린지다. 만화 ''헌터x헌터''의 곤이 춤추는 영상에 이 곡을 입힌 틱톡 영상에서 퍼졌고, 곡과 춤, 캐릭터가 서로 아무 상관없이 하나로 합쳐졌다는 점이 밈의 재미로 꼽힌다. 반복되는 후렴과 느긋한 분위기 덕에 중독성이 강해 아이돌과 인플루언서까지 릴스와 쇼츠로 따라 했다. 알파벳 T를 이용한 MBTI 말장난 패러디도 나왔다. 곡 이름은 ''티라미수 케이크''가 맞는 표기지만 이 밈에서는 ''케익''이 더 널리 쓰인다.',
  origin = '정확한 최초 게시 시점은 확인하지 못했다. 2024년 틱톡에서 한 이용자가 곤이 춤추는 영상에 위아더나잇의 ''티라미수 케익''(2015년 4월 발매)을 입혀 올린 것이 퍼진 것으로 소개된다. 춤 동작은 중국 그룹 젓가락 형제의 ''Little Apple'' 안무에서 왔다는 설명이 있다. 이후 더보이즈, 아이브 레이, NCT 등이 따라 하며 확산됐다.',
  usage_note = '유행하는 짧은 춤을 가볍게 따라 하는 릴스나 쇼츠 영상, 또는 친구들과 장난스럽게 찍는 단체 촬영에 어울린다. 오래된 곡이 한순간에 다시 인기를 얻은 사례를 설명할 때도 인용된다.',
  caution = '곡, 춤, 캐릭터의 출처가 각각 달라 하나의 공식 안무나 공식 캠페인처럼 소개하면 사실과 맞지 않는다. 광고나 상업 영상에 곡과 만화 캐릭터를 그대로 쓰면 저작권 문제가 생길 수 있으니 개인 놀이 수준을 넘길 때는 주의해야 한다.',
  usage_examples = '[{"situation":"인스타그램 릴스 캡션","text":"퇴근하자마자 거울 앞에서 티라미수 케익 챌린지 5번째 도전 중ㅋㅋ"},{"situation":"친구들과의 단톡방","text":"레이도 했다는데 우리도 오늘 모이면 티라미수 케익 챌린지 찍자"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'a8txvsut'
  and slug = '티라미수-케익-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

