-- 너 T야? (chmhpbjd / 너-T야?)
update public.memes set
  description = '성격 유형 검사 MBTI에서 T는 사고형을 뜻하며, 감정보다 논리와 효율을 앞세운다고 여겨진다. ''너 T야?''는 상대가 내 감정에 공감하는 대신 사실이나 해결책만 말할 때 그 점을 짚으며 장난스럽게 되묻는 말이다. 공감 못 하는 사람이라는 놀림이 담겨 있다. 손가락이나 마늘 같은 물건으로 T 모양을 만들어 보이거나 음절을 뒤집고 T로 끝나는 말을 붙이는 식으로 변형도 많다. 일상 대화와 방송에까지 퍼져 T와 F를 가르는 기준이 사실상 공감 여부로 굳어졌다는 평가도 나왔다.',
  origin = '2023년 초 유튜브 코미디 채널 ''밈고리즘''의 ''폭스클럽'' 시리즈 영상에서 들뜬 말을 곧이곧대로 받아들인 상대에게 "T야?"라고 되묻는 장면이 화제가 되며 퍼졌다. 이후 틱톡과 유튜브, 온라인 커뮤니티를 거쳐 일상 말투로 자리 잡았다. 영상이 올라온 정확한 시점은 매체마다 달리 전한다.',
  usage_note = '친구가 속상한 일을 털어놓는데 해결책부터 내놓거나, 들뜬 말에 사실 관계를 따지며 찬물을 끼얹었을 때 웃으며 던지는 식으로 어울린다. 서로 MBTI 이야기를 편하게 하는 사이에서 효과가 좋다.',
  caution = 'T 유형이 공감을 못 한다는 단정이 깔려 있어서 진지한 대화나 갈등 상황에서 쓰면 상대를 비난하는 말로 들린다. 실제로 T 유형이라는 이유로 따돌림을 호소하거나 MBTI를 숨기는 사례가 보도된 만큼 놀림이 지나치지 않게 해야 한다.',
  usage_examples = '[{"situation":"친구 단톡방에서 시험 망쳤다는 하소연에 다른 친구가 공부법부터 말할 때","text":"야, 지금 위로가 필요한 건데 해결책부터 말하냐ㅋㅋ 너 T야?"},{"situation":"직장 동료와 점심시간 잡담","text":"비 와서 우울하다니까 우산 챙겨 다니면 된다고? 너 T야?ㅋㅋ"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'chmhpbjd'
  and slug = '너-T야?'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

