-- 꿍싯꿍싯 챌린지 (5u8q26cc / 꿍싯꿍싯-챌린지)
update public.memes set
  description = 'NCT WISH 료의 안무 한 동작을 잘라 일본 듀오 할칼리의 ''오츠카레 썸머''에 입힌 팬 편집 영상에서 시작된 춤 밈이다. 소속사가 밀던 공식 챌린지가 아니라 팬들이 영상 속 장난스러운 동작에 ''꿍싯꿍싯''이라는 이름을 붙이며 퍼졌고, 이른바 역챌린지로 불린다. 곡과 동작이 원래 서로 다른 곳에서 나왔다는 점이 재미 포인트이며, 에스파 카리나, 아이브 레이 같은 아이돌까지 따라 해 화제성이 커졌다. 팬덤 콘텐츠와 커버 영상에서 주로 쓰이며, 발매 후 시간이 지난 뒤에도 자발적인 참여가 이어졌다고 보도됐다.',
  origin = '2026년 한 팬이 NCT WISH 료의 직캠에서 마지막 안무 부분을 떼어내 ''오츠카레 썸머''(할칼리, 2003년 곡)에 입혀 올린 편집 영상에서 시작됐다고 보도됐다. 팬들이 이를 ''꿍싯꿍싯''이라 부르며 퍼졌고, 카리나와 레이, 르세라핌 사쿠라, SHINee 멤버들도 참여한 것으로 전해진다. 편집 영상을 처음 올린 팬이 누구인지는 확인되지 않았다.',
  usage_note = '아이돌 팬덤 콘텐츠나 커버 댄스, 친구들과 찍는 짧은 춤 영상에서 가볍게 따라 할 때 어울린다. 공식 안무가 아니라 팬들이 만든 놀이라는 점을 알고 쓰면 자연스럽다.',
  caution = '특정 멤버의 동작을 편집한 팬 영상에서 출발해 공식 안무가 아니므로 공식 챌린지처럼 소개하면 사실과 다르다. 멤버 개인을 놀리는 듯한 영상이나 직캠을 무단으로 퍼 나르는 방식으로 쓰면 팬덤 안에서 반감을 살 수 있다.',
  usage_examples = '[{"situation":"팬덤 단톡방","text":"카리나도 꿍싯꿍싯 했더라 이제 우리도 연습해야 되는 거 아니냐ㅋㅋ"},{"situation":"릴스 캡션","text":"친구랑 연습실에서 꿍싯꿍싯 챌린지 도전! 제발 박자만 맞아라"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '5u8q26cc'
  and slug = '꿍싯꿍싯-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

