-- 마네킹 챌린지 (94bhhfek / 마네킹-챌린지)
update public.memes set
  description = '여러 사람이 마네킹처럼 동작을 멈춘 채 그대로 굳어 있고, 카메라가 그 사이를 천천히 지나가며 촬영하는 영상 놀이다. 대부분의 영상에는 래퍼 듀오 Rae Sremmurd의 ''Black Beatles''가 배경음악으로 깔렸고, 이 듀오는 콘서트에서 직접 챌린지를 선보이기도 했다. 고등학생 치어리더부터 NBA와 NFL 팀, 대학 미식축구 팀까지 단체 영상을 올렸다. 한국에는 2016년 말 전해져 여자친구, 우주소녀, 세븐틴, 블랙핑크 등 K팝 그룹이 따라 했고, 블랙핑크는 시상식, 펜타곤은 컴백 예고와 엮은 영상을 올렸다.',
  origin = '2016년 10월 말부터 미국 온라인에 영상이 올라오기 시작했다고 AP는 전한다. 11월 초에는 텍사스의 고등학교 치어리더와 NBA 밀워키 벅스, 피츠버그 스틸러스 등이 참여했고, 한국에는 2016년 말 전해져 아이돌 그룹들이 영상을 올렸다. 최초 게시자는 열어본 자료에서 확인하지 못했다.',
  usage_note = '여럿이 한순간 동작을 멈추고 찍는 단체 사진이나 영상, 또는 과거 유행한 챌린지를 설명할 때 어울린다. 학교 행사, 동아리 모임에서 추억용 영상으로 쓰기 좋다.',
  caution = '오래 정지한 자세를 유지하다 보면 균형을 잃거나 위험한 곳에서 다칠 수 있어서 계단, 도로 등에서는 찍지 않는 것이 좋다. 영상에 나온 사람들의 동의 없이 공개하면 초상권 문제가 생길 수 있다.',
  usage_examples = '[{"situation":"동아리 단톡방","text":"종강 기념으로 다 같이 마네킹 챌린지 한 번 찍자. 아무도 움직이면 안 돼ㅋㅋ"},{"situation":"옛날 영상 올린 SNS 게시글","text":"2016년에 유행하던 마네킹 챌린지, 다시 보니까 은근 추억이다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '94bhhfek'
  and slug = '마네킹-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

