-- 형님먼저 아우먼저 (xawqwxax / 형님먼저-아우먼저)
update public.memes set
  description = '''형님 먼저, 아우 먼저''는 농심라면의 광고 문구로 유명해진 말이다. 서로 상대를 먼저 챙기며 양보하는 뜻으로 읽혀서, 음식을 권하거나 순서를 양보하는 장면에서 정겨운 농담으로 인용된다. 이 문구는 1975년 농심라면이 출시될 때의 광고 카피였고, 당시 롯데공업이던 회사가 1978년 사명을 농심으로 바꾸는 계기가 된 라면의 대표 카피로 알려져 있다. 2025년에 농심이 창립 60주년을 맞아 농심라면을 다시 내놓으면서 이 문구도 현대적으로 재해석되었다.',
  origin = '1975년 농심라면 출시 때의 광고 카피로 전해진다. 당시 25원이던 이 라면은 정겨운 카피 덕에 전국적으로 인기를 얻었고, 회사가 1978년 농심으로 이름을 바꿀 때 이 라면이 사명의 유래가 되었다고 한다. 2025년에는 출시 당시 포장 디자인을 이어받은 재출시판이 나왔다. 광고에 출연한 인물은 열어본 자료에서 확인하지 못했다.',
  usage_note = '여럿이 음식을 나누거나 마지막 한 점을 서로 양보할 때, 문을 먼저 지나가라고 권할 때 장난스럽게 인용하면 어울린다. 어른 세대와 대화할 때 옛 광고 이야기로 친근함을 더하기에도 좋다.',
  caution = '형과 아우를 가르는 표현이라 나이나 성별, 직급에 따른 위계를 강조하는 말로 들릴 수 있다. 격식 있는 자리에서 윗사람에게 먼저 하라는 뜻으로 가볍게 던지면 오히려 무례해 보일 수 있으니 친한 사이에서만 쓰는 것이 좋다.',
  usage_examples = '[{"situation":"회식 자리에서 마지막 만두 한 알이 남았을 때","text":"마지막 건 형님먼저 아우먼저~ 식기 전에 누가 드세요ㅋㅋ"},{"situation":"팀 단톡방에서 점심 메뉴를 정할 때","text":"저는 다 괜찮아요. 형님먼저 아우먼저, 먹고 싶은 거 먼저 고르세요!"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'xawqwxax'
  and slug = '형님먼저-아우먼저'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

