-- 멧챠 카멜레온 (b97ffh93 / 멧챠-카멜레온)
update public.memes set
  description = '일본의 개인 개발자 레모리온이 만든 멀티플레이 숨바꼭질 게임 ‘멧챠 카멜레온’과, 이 게임을 소재로 한 숏폼 영상을 가리킨다. 숨는 쪽은 하얀 카멜레온 캐릭터의 몸에 직접 색과 무늬를 칠해 벽, 사물, 바닥과 비슷하게 만든 뒤 맵 곳곳에 숨고, 찾는 쪽은 제한 시간 안에 숨은 플레이어를 찾아내야 한다. 다른 사물로 변신하는 기존 숨바꼭질 게임과 달리 그림 실력과 자리 선정이 승패를 가른다. 그래서 분명 화면에 있는데 안 보이는 위장 영상, 뻔한 곳에 숨었다가 들키는 웃긴 장면이 유튜브 쇼츠와 인스타그램 릴스에서 널리 퍼졌다. 가격이 낮고 규칙이 단순해 친구끼리 함께 하기 좋다는 점도 흥행 요인으로 꼽힌다.',
  origin = '2026년 6월 10일 스팀에 출시됐다. 레모리온(레모리온_1224)이 약 두 달 만에 만들었고, 아트 협업자를 포함해 2인 개발로 소개하는 매체도 있다. 별도 퍼블리셔나 대규모 마케팅 없이 스트리머 방송과 숏폼 영상, 입소문으로 퍼져 출시 약 2주 만에 1천만 장, 한 달 만에 1천5백만 장을 넘겼다고 보도됐다.',
  usage_note = '잘 위장한 사진이나 영상을 올리면서 여기 사람이 숨어 있다고 소개할 때, 또는 친구들과 이 게임을 같이 하자고 제안할 때 쓴다. 게임 이름이자 영상 장르를 가리키는 말이라 게임을 모르는 사람에게는 설명을 덧붙이는 편이 좋다.',
  caution = '특정 게임의 이름이라 유행이 지나면 맥락 없이 쓰기 어렵고, 판매량 같은 수치는 보도 시점마다 달라 단정해서 말하면 틀릴 수 있다. 위장 영상을 올릴 때 다른 사람의 플레이 화면이나 방송 클립을 허락 없이 가져오면 저작권 문제가 될 수 있다.',
  usage_examples = '[{"situation":"단톡방","text":"멧챠 카멜레온 같이 하자, 오늘 저녁에 다들 접속 가능해?"},{"situation":"SNS 캡션","text":"이 사진 속에 숨어 있는 사람 찾아봐, 멧챠 카멜레온급 위장이다 ㅋㅋ"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'b97ffh93'
  and slug = '멧챠-카멜레온'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

