-- 히딩크 "나는 아직 배가 고프다" (gnact78h / 히딩크-"나는-아직-배가-고프다")
update public.memes set
  description = '2002 한일월드컵 당시 거스 히딩크 감독이 ‘I’m still hungry’라고 한 말로 알려진 어록이다. 한국어로는 ‘나는 아직도 배가 고프다’, ‘난 아직도 배가 고프다’ 등으로 옮겨 쓰며, 여기서 배고픔은 음식이 아니라 더 높은 성과에 대한 갈증을 뜻한다. 한국이 포르투갈을 꺾고 처음으로 16강 진출을 확정한 뒤 나온 말로 소개되며, 현재의 성과에 만족하지 않고 한 단계 더 나아가겠다는 태도를 상징하는 표현으로 자리 잡았다. 이후에도 축구 기사의 제목으로 인용됐고, 2012년에는 K리그 올스타전 홍보 영상에서 히딩크가 이 말을 다시 꺼내기도 했다. 요즘은 스포츠뿐 아니라 시험, 취업, 업무에서 목표를 이룬 뒤 더 하겠다는 다짐을 밝힐 때도 인용된다.',
  origin = '2002년 한일월드컵에서 한국이 포르투갈을 꺾고 16강 진출을 확정한 직후 히딩크 감독이 ‘I’m still hungry’라고 말한 것으로 보도됐다. 한국어 번역 표현은 매체마다 조금씩 다르다. 확인한 기사에는 발언이 나온 정확한 자리나 원문 인터뷰가 나오지 않는다.',
  usage_note = '목표를 이뤘지만 안주하지 않고 다음 단계를 노린다고 말할 때 어울린다. 승진, 합격, 우승 같은 성과를 축하하는 자리에서 겸손하게 포부를 밝히는 문장으로 가볍게 인용하면 자연스럽다.',
  caution = '원래 의미는 성과에 대한 열망이라 단순히 음식을 더 먹겠다는 농담으로 쓰면 다른 뜻으로 읽힐 수 있다. 또 만족하지 말라는 압박으로 상대에게 들이밀면 과로를 부추기는 말처럼 들려 불쾌할 수 있으니, 남에게 강요하는 투로는 피하는 것이 좋다.',
  usage_examples = '[{"situation":"직장 메신저","text":"프로젝트 오픈은 성공했지만 나는 아직도 배가 고프다, 다음 분기 목표도 같이 잡아봅시다."},{"situation":"SNS 댓글","text":"예선 통과했다고 끝이 아니죠, 나는 아직도 배가 고프다는 마음으로 본선 갑니다."}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'gnact78h'
  and slug = '히딩크-"나는-아직-배가-고프다"'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

