-- 나니가스키 챌린지 (jehcehhf / 나니가스키-챌린지)
update public.memes set
  description = '일본 애니메이션 프랜차이즈 러브라이브!의 유닛 AiScReam이 부른 곡 ‘Ai♡Scream!’의 부름과 대답 구간에서 나온 숏폼 챌린지다. ‘나니가 스키’는 일본어로 뭘 좋아해라는 뜻이며, 노래의 해당 구간에 맞춰 귀여운 포즈와 표정을 짓는 방식으로 따라 한다. 2025년 2월 투어 공연 장면을 러브라이브 공식 틱톡이 올리면서 며칠 만에 조회수 1천만 회를 넘겼고, 애니메이션 코스프레나 자동차 헤드라이트 립싱크 같은 다양한 패러디로 이어졌다. 한국에서도 에스파, 엔시티 위시 멤버 등 아이돌이 따라 하는 영상을 올렸고, 노래를 느린 R&B 풍으로 바꾼 리믹스 버전도 나왔다. 일본에서는 틱톡 어워즈 재팬 2025에서 올해의 비디오 상을 받았다.',
  origin = '러브라이브! 시리즈 아시아 투어(2025년 2월)에서 AiScReam이 선보인 ‘Ai♡Scream!’의 부름과 대답 구간이 출발점이다. 러브라이브 공식 틱톡이 이 장면을 올린 뒤 알고리즘을 타고 며칠 만에 1천만 회 넘게 재생됐고, 2025년 11월 무렵에는 2천5백만 회를 넘겼다고 한다. 한국에서는 2025년 5월 기사에서 이미 아이돌들의 참여 영상과 리믹스 버전이 소개됐다.',
  usage_note = '좋아하는 가수, 음식, 취미를 소개하는 영상이나 최애 자랑 게시물에 곁들여 쓰기 좋다. 노래의 귀여운 분위기에 맞춰 가볍고 장난스러운 톤으로 올릴 때 어울린다.',
  caution = '원곡은 특정 애니메이션 유닛의 곡이라 해당 작품을 모르는 사람에게는 맥락이 전달되지 않을 수 있다. 영상에 원곡 음원이나 공연 화면을 그대로 가져와 올리면 플랫폼의 음원 사용 정책과 저작권에 걸릴 수 있으니 주의해야 한다.',
  usage_examples = '[{"situation":"틱톡 챌린지","text":"나니가 스키? 나는 새벽 두 시에 먹는 라면이 제일 좋아!"},{"situation":"단톡방","text":"우리 점심 메뉴 나니가 스키 챌린지로 정하자, 다들 좋아하는 거 하나씩 말해봐"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'jehcehhf'
  and slug = '나니가스키-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

