-- 라면 꿀조합 (df32nsbg / 라면-꿀조합)
update public.memes set
  description = '‘꿀조합’은 시판 음식이나 음료를 서로 섞거나 재료를 더해 더 맛있게 만드는 조합을 가리키는 말이고, ‘라면 꿀조합’은 그중 라면에 반숙란, 치즈, 소시지, 만두 같은 재료를 더하거나 다른 제품과 섞어 먹는 방법을 뜻한다. 편의점 컵라면에 볶음 김치와 소시지를 넣어 부대찌개처럼 먹거나, 불닭볶음면에 삼각김밥과 스트링 치즈를 얹어 볶음밥처럼 먹는 조합이 대표적이다. SNS에서 라면 꿀조합 레시피가 흔한 검색어가 되었고, 일부 조합은 실제 제품 출시로 이어지기도 했다. 팔도 왕뚜껑 국물라볶이는 떡, 반숙란, 치즈 등을 더하는 SNS 레시피가 인기를 끌며 출시 약 4개월 만에 600만 개 넘게 팔렸다고 보도됐다.',
  origin = '특정 시작 시점이 있는 유행어라기보다 소비자가 시판 제품을 자기 방식으로 바꿔 먹는 문화에서 자랐다. 2018년 인사이트 기사에 이미 편의점 꿀조합 레시피로 부대찌개 컵라면과 사리곰탕 만둣국 등이 소개됐다. 2026년 한국일보 보도는 10~30대가 주도하는 모디슈머 흐름 속에서 식품업체가 이런 조합을 제품에 반영한다고 전했다.',
  usage_note = '편의점이나 집에서 라면을 더 맛있게 먹는 방법을 묻거나 공유할 때 쓴다. 재료와 순서, 조리 시간을 함께 적으면 따라 하기 쉬운 레시피 글이 된다.',
  caution = '전자레인지로 컵라면을 조리하는 조합은 용기가 전자레인지용인지 먼저 확인하지 않으면 용기가 변형되거나 뜨거운 국물이 튀어 화상을 입을 수 있다. 또 치즈나 소스를 더하면 나트륨과 열량이 크게 늘 수 있으니 건강 상태를 고려해야 한다.',
  usage_examples = '[{"situation":"편의점 앞 단톡방","text":"컵라면에 볶음김치랑 소시지 넣으면 부대찌개 맛 난대, 오늘 이 꿀조합 해보자"},{"situation":"SNS 댓글","text":"불닭에 스트링치즈 얹는 라면 꿀조합 알려줘서 고마워요, 맵찔이라 살았어요"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'df32nsbg'
  and slug = '라면-꿀조합'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

