-- 간바레 챌린지 (r46decj8 / 간바레-챌린지)
update public.memes set
  description = '일본의 음악 크리에이터 오다마요네즈가 만든 곡 ‘頑張りたい人へ’(응원하고 싶은 사람에게)에 맞춰 만드는 숏폼 챌린지다. 한 사람이 화면을 세 칸으로 나누고, 리듬에 맞춘 손가락 튕기기와 손을 펼치는 동작을 보여 준 뒤 ‘간바레 하잇!’ 타이밍에 세 칸 모두에 등장하는 연출로 구성한다. 화려한 안무 대신 컷 분할과 등장 타이밍이 핵심이라 누구나 따라 하기 쉽고, 개강, 출근, 다이어트처럼 여러 상황에 가벼운 응원을 붙일 수 있다. 일본에서 먼저 유행한 뒤 한국으로 넘어왔고, 2026년 2월 말 걸그룹 CSR의 유나가 일본 투어 중 만든 영상을 계기로 장원영, 범규, 승관 등 아이돌의 참여 영상이 이어졌다.',
  origin = '음원은 일본 음악 크리에이터 오다마요네즈의 ‘頑張りたい人へ’로, 일본에서 숏폼 챌린지로 먼저 유행했다. 한국에서는 CSR의 유나가 2026년 2월 말 일본 투어 중 만든 영상이 계기가 됐고, 스포츠경향은 이 영상이 약 900만 조회를 기록했다고 전하며 ‘원조’ 간바레 챌린지로 소개했다. 릴스, 틱톡, 유튜브에서 수천 개의 영상이 올라왔다고 한다.',
  usage_note = '자기소개나 근황 영상에서 리듬, 동작, 표정을 한 화면에 담고 싶을 때 쓰기 좋다. 응원하는 대상을 정해 간바레라는 가벼운 응원 메시지를 붙이면 개강, 시험, 출근 같은 시즌 소재와도 어울린다.',
  caution = '원곡 음원과 타인의 영상을 편집에 쓰면 저작권이나 플랫폼 음원 정책 문제가 생길 수 있다. 한국에서는 특정 아이돌의 영상이 원조로 소개되지만 음원과 형식은 일본에서 먼저 유행했으니, 출처를 말할 때 이를 구분하지 않으면 오해를 낳을 수 있다.',
  usage_examples = '[{"situation":"인스타그램 릴스 캡션","text":"개강 첫 주 버티는 중, 나한테 하는 간바레 챌린지 ㅋㅋ"},{"situation":"단톡방","text":"우리 동기들끼리 간바레 챌린지 3분할로 찍어서 팀 응원 영상 만들자"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'r46decj8'
  and slug = '간바레-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

