-- 삐끼삐끼 챌린지 (u5a9yfwr / 삐끼삐끼-챌린지)
update public.memes set
  description = '프로야구 KIA 타이거즈 치어리더들이 투수가 상대 타자를 삼진으로 잡았을 때 추는 응원 춤에서 비롯된 댄스 챌린지다. 치어리더들이 줄지어 서서 엄지를 세우고 드럼 비트에 맞춰 몸을 흔드는 단순한 동작이며, 삼진을 당한 상대를 살짝 놀리는 듯한 분위기가 재미 포인트로 소개된다. 곡 이름의 ''삐끼삐끼''는 노래에서 반복되는 소리에서 따온 것이다. 2024년 7월 말에서 8월 초 사이 이주은 치어리더가 화장을 고치다 음악이 나오자 급히 일어나 춤추는 직캠이 SNS에서 화제가 되면서 따라 하기 열풍이 일었고, 인플루언서와 해외 이용자까지 참여했다.',
  origin = 'KIA는 2021년경부터 틱톡·유튜브에 돌던 리믹스 곡을 2022년 3월 치어리더팀과 논의해 공식 아웃송으로 정했고, 안무도 치어리더팀의 아이디어였다. 원곡은 H.O.T. 출신 세 사람으로 이뤄진 JTL이 2001년 12월 낸 ''마이 레콘''이며, 리믹스는 BPM을 130으로 높이고 베트남식 비나하우스 스타일로 바꾼 것이다. 이주은 직캠은 2024년 8월 1일 기준 약 5800만 회 조회됐고, 같은 달 27일 뉴욕타임스가 한국 치어리더들의 틱톡 인기를 다뤘다.',
  usage_note = '신나는 모임이나 응원 분위기에서 엄지를 세우고 몸을 흔드는 동작을 가볍게 따라 할 때, 또는 상대의 실수를 장난스럽게 넘기는 장면에 잘 어울린다.',
  caution = '원래 삼진을 당한 상대 타자를 놀리는 성격의 응원 동작이라, 진지하게 낙담한 사람이나 경기에서 진 쪽 앞에서 추면 비꼬는 것처럼 보일 수 있다. 영상 속 특정 치어리더의 외모나 사생활을 평가하는 댓글로 번지지 않게 주의한다.',
  usage_examples = '[{"situation":"단톡방에서 친구가 퇴근 직전 업무를 끝냈다고 자랑할 때","text":"방금 그거 삐끼삐끼 각이다ㅋㅋ 엄지 척 올리고 퇴근해"},{"situation":"회식 자리 숏폼 영상 캡션","text":"팀장님 건배사 끝나자마자 다 같이 삐끼삐끼 챌린지 찍음"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'u5a9yfwr'
  and slug = '삐끼삐끼-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

