-- SG워너비 - Timeless (xm89ke6m / SG워너비---Timeless)
update public.memes set
  description = '''Timeless''는 SG워너비의 데뷔곡이자 첫 앨범 ''SG Wanna Be+''의 타이틀곡이다. 위키백과는 이 곡을 미디엄템포 R&B 곡으로 분류하며, 당시로서는 큰 제작비를 들인 뮤직비디오에 이름 있는 배우들이 출연해 화제가 됐다. 이후 SG워너비는 2005년 2집 등으로 인기를 이어가 골든디스크 대상을 세 차례 받았다. 이 곡은 발매 17년 가까이 지난 2021년 4월에도 다시 주목받았다. 그룹이 MBC 예능에 출연한 직후 벅스와 지니 실시간 차트 1위에 올랐다.',
  origin = '2004년 1월 SG워너비의 첫 앨범 타이틀곡으로 발표됐다(위키백과는 발매일을 1월 20일로 적는다). 2005년 레이디경향 기사는 이 곡과 뮤직비디오가 그룹보다 먼저 주목받았다는 멤버들의 말을 전한다. 2021년 4월 17일 그룹의 MBC 예능 출연을 계기로 음원 차트에 다시 올랐다.',
  usage_note = '2000년대 중반 감성이나 노래방 추억을 이야기할 때, 또는 오래된 노래가 다시 차트에 오르는 현상을 예로 들 때 어울린다.',
  caution = '2021년에 다시 차트에 오른 적이 있어 ''옛날 노래''로만 소개하면 요즘 반응과 어긋날 수 있다. 가사나 음원을 그대로 옮겨 올리면 저작권 문제가 생길 수 있으니 곡명과 감상만 언급하는 것이 안전하다.',
  usage_examples = '[{"situation":"카카오톡 단톡방에서 옛 노래 플레이리스트를 공유하며","text":"오늘 퇴근길엔 SG워너비 Timeless 들었다. 2004년 노래인데 아직도 가슴이 뛰네"},{"situation":"유튜브 댓글","text":"Timeless는 17년 만에 다시 차트 1위 찍은 게 진짜 이해된다. 이 시절 보컬이 괜히 전설이 아니야"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'xm89ke6m'
  and slug = 'SG워너비---Timeless'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

