-- 매끈매끈하다 챌린지 (c92pedkz / 매끈매끈하다-챌린지)
update public.memes set
  description = '프랑스 출신 안무가 카니가 한국어 형용사를 외우려고 즉석에서 만든 율동 섞인 읊조림에서 시작된 밈이다. 영상에서 카니는 ''매끈매끈하다'', ''울퉁불퉁하다'', ''평평하다'' 같은 단어를 리듬에 맞춰 반복하며 동작을 붙여 외운다. 중독성 있는 리듬 덕에 샤이니 키를 시작으로 투어스, 하츠투하츠, 제로베이스원, 트와이스, 르세라핌 등이 따라 하는 챌린지로 번졌다. ''○○하다, ○○한'' 구조를 강아지나 디저트 같은 일상 소재에 붙이는 패러디도 생겼다. 수능을 며칠 앞두고 퍼져 머릿속을 떠나지 않는 곡을 뜻하는 ''수능 금지곡''이라는 별명도 얻었다.',
  origin = '2025년 10월 29일 MBC 유튜브 채널 ''광''의 웹예능 ''카니를 찾아서''에 올라온 영상(EP.20)에서 카니가 한국어를 공부하며 단어를 외우는 장면이 발단이다. 이 장면이 SNS에서 화제가 된 뒤 카니가 키와 함께 찍은 챌린지 영상이 확산의 계기가 됐고, 2025년 11월 수능을 앞둔 시기와 겹치며 널리 퍼졌다.',
  usage_note = '중독성 강한 숏폼 챌린지를 소개하거나, 형용사를 반복해 외우는 장난스러운 말투를 흉내 낼 때 어울린다. 수능 시즌의 ''수능 금지곡'' 농담으로도 쓰인다.',
  caution = '수능을 앞둔 수험생에게 이 영상을 보내면 공부를 방해한다는 농담으로 받아들여질 수 있다. 한국어를 배우는 외국인의 말투나 억양을 놀리듯 흉내 내는 방식으로 쓰면 무례하게 보일 수 있다.',
  usage_examples = '[{"situation":"수능을 앞둔 가족 단톡방","text":"이거 절대 보지 마 ㅋㅋ 머리에 박혀서 매끈매끈하다 매끈매끈한만 맴돌아"},{"situation":"인스타그램 릴스 캡션","text":"우리 학과 단체로 매끈매끈하다 챌린지 도전, 마지막 컷에서 다 같이 평평해짐"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'c92pedkz'
  and slug = '매끈매끈하다-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

