-- 아무노래 챌린지 (rnyv6jwt / 아무노래-챌린지)
update public.memes set
  description = '2020년 1월 지코가 신곡 ''아무노래'' 공개를 앞두고 인스타그램에 올린 춤 영상에서 시작된 챌린지다. 지코는 마마무 화사와 함께 춘 영상을 올린 뒤 청하 등과도 영상을 이어 올렸고, 이효리, 크러쉬, 송민호 같은 연예인이 잇따라 참여했다. #아무노래챌린지 해시태그로 퍼졌으며 틱톡에서도 큰 호응을 얻어, 뉴시스는 업로드가 130만 건, 조회가 4억 회를 넘었다고 보도했다. 참여자마다 표정과 분위기가 달라 누구의 영상이 가장 어울리는지 비교하는 기사도 나왔다.',
  origin = '위키트리는 지코가 곡 발매 하루 전인 2020년 1월 12일 인스타그램에 화사와 춤추는 영상을 올리며 챌린지를 시작했다고 전한다. 곡은 1월 13일 발매돼 14일 오전 주요 음원 차트 1위에 올랐고, 같은 날 청하와의 영상과 이효리의 참여 영상이 이어졌다. 이후 틱톡 중심으로 확산됐다.',
  usage_note = '유행했던 신곡 챌린지의 사례를 이야기하거나, 부담 없이 가볍게 참여하는 영상 콘텐츠를 소개할 때 언급하기 좋다.',
  caution = '2020년 초에 유행한 챌린지라 지금 쓰면 한참 지난 유행으로 느껴질 수 있다. 영상에 노래 원본을 그대로 쓸 때는 플랫폼별 음원 사용 규정과 업무용 계정의 게시 기준을 확인해야 한다.',
  usage_examples = '[{"situation":"직장 메신저 점심시간 잡담","text":"아무노래 챌린지 때 생각난다. 그땐 진짜 온 국민이 다 찍었잖아요"},{"situation":"SNS 댓글","text":"그때 지코랑 화사 아무노래 챌린지 보고 처음으로 따라 해 봄ㅋㅋ"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'rnyv6jwt'
  and slug = '아무노래-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

