-- 산타는 없거든 (aufsna4z / 산타는-없거든)
update public.memes set
  description = 'Mnet 〈쇼미더머니6〉 팀 배틀에서 래퍼 우원재가 당시 13세 참가자 조우찬을 향해 던진 디스 가사에서 나온 표현이다. 울어도 괜찮다고 다독이는 듯하다가 어차피 산타는 없다고 덧붙여 어린 상대의 동심을 건드리는 구조라, 거친 욕설 없이도 상대를 놀리는 재치 있는 디스로 받아들여졌다. 조우찬이 곧바로 ''똑바로 해 원재야''라고 맞받아 현장 분위기도 달아올랐다. 방송 직후 클립이 SNS와 온라인 커뮤니티로 빠르게 퍼졌고, 이 문구는 상대의 순진한 기대나 환상을 깨는 농담으로 인용되기도 한다.',
  origin = '2017년 8월 11일 방송된 〈쇼미더머니6〉 7회 팀 배틀에서 우원재가 조우찬을 상대로 한 디스 랩에서 나왔다. 보도에 따르면 방송 직후 장면이 SNS와 커뮤니티로 퍼지며 누리꾼 사이에서 우원재의 명장면 중 하나로 꼽혔다. 이 배틀에서는 다이나믹 듀오 팀이 이겼고 우원재 쪽 에이솔이 탈락 후보로 지목됐다.',
  usage_note = '친구의 순진한 기대나 환상을 장난스럽게 깨뜨릴 때, 또는 ''울어도 돼''라며 놀리듯 다독이는 상황에서 어울린다. 크리스마스 시즌 단톡방 농담으로 쓰기도 좋다.',
  caution = '원래 상대를 겨냥한 디스 가사이므로 어린아이나 진지하게 기대하고 있는 사람에게 던지면 놀림이나 상처로 읽힐 수 있다. 가까운 사이의 농담에 한정하고, 아이 앞에서 동심을 깨는 말로 쓰는 일은 피하는 편이 좋다.',
  usage_examples = '[{"situation":"크리스마스를 앞둔 단톡방","text":"선물 기대하는 거야? 울어도 돼, 산타는 없거든."},{"situation":"직장 동료와 메신저","text":"이번 달 성과급 나올 거라고 믿는 거야? 걱정 마, 울어도 돼. 산타는 없거든."}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'aufsna4z'
  and slug = '산타는-없거든'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

