-- 안 나오면 쳐들어간다 (xedax3m5 / 안-나오면-쳐들어간다)
update public.memes set
  description = 'tvN 〈놀라운 토요일〉에서 방송인 붐이 걸그룹 아일릿의 신곡 ''잇츠 미'' 무대를 보다가 비트에 맞춰 즉흥으로 외친 말이 밈이 된 것이다. 원곡 박자에 어색할 만큼 잘 맞아 스튜디오가 웃음바다가 됐고, 팬들 사이에서는 이 외침이 원곡보다 중독적이라는 반응이 나왔다. 아일릿은 공식 계정으로 붐이 테크노 비트 위에서 이 말을 외치는 리믹스 챌린지 영상을 공개해 밈을 활동 콘텐츠로 끌어들였다. 말뜻은 문 앞에서 나오지 않으면 쳐들어가겠다는 장난스러운 엄포라서, 약속 장소에 나타나지 않는 친구를 재촉하는 농담으로도 쓸 수 있다.',
  origin = 'MHN스포츠 보도에 따르면 2026년 5월 2일 방송된 〈놀라운 토요일〉에서 붐이 아일릿의 ''잇츠 미'' 무대 직후 이 말을 외쳤고 장면이 온라인으로 퍼졌다. 5월 9일에는 아일릿이 붐이 참여한 리믹스 챌린지 영상을 공식 계정에 올렸고, 같은 날 열린 팬 미팅에서는 멤버들도 몰랐던 리믹스 버전이 깜짝 공개됐다.',
  usage_note = '신곡 챌린지나 예능 패러디 영상에 쓰기 좋고, 약속에 늦는 친구를 가볍게 재촉하는 단톡방 농담으로도 어울린다. 리믹스 비트에 맞춰 외치면 원래 장면의 맛이 산다.',
  caution = '특정 가수의 활동곡과 엮인 밈이라 곡이나 방송을 모르는 사람에게는 뜻이 잘 전달되지 않는다. 문자 그대로는 협박처럼 들리는 말이므로 실제로 화가 난 상황이나 진지한 갈등 장면에서 쓰면 오해를 살 수 있고, 모르는 사람의 집이나 사무실을 두고 농담하는 것은 피해야 한다.',
  usage_examples = '[{"situation":"약속에 늦는 친구에게 보내는 단톡방 메시지","text":"집 앞인데 안 나오면 쳐들어간다 진짜ㅋㅋ"},{"situation":"아일릿 리믹스 챌린지 영상 캡션","text":"붐 버전 리믹스에 맞춰 찍어봤다. 안 나오면 쳐들어간다!"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'xedax3m5'
  and slug = '안-나오면-쳐들어간다'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

