-- 나 지금 떨고 있니 (aqerjbu7 / 나-지금-떨고-있니)
update public.memes set
  description = '1995년 SBS 드라마 〈모래시계〉에서 조직폭력배 박태수(최민수)가 사형 집행을 앞두고 읊조린 대사에서 나온 말이다. 사형을 앞둔 인물이 던진 말이라 극적인 무게가 있고, 친구인 검사 강우석과 처지가 갈린 장면의 대비 때문에 드라마를 대표하는 명대사로 기억된다. 표기는 ''나 지금 떨고 있니?'', ''나, 떨고 있냐''처럼 출처마다 조금씩 다르다. 일상에서는 면접, 발표, 시험 결과를 기다리는 상황처럼 긴장한 자신이나 상대를 비장하게 꾸며 말하는 농담으로 쓸 수 있고, 원래 장면의 무게와 사소한 긴장 사이의 낙차가 웃음 포인트가 된다.',
  origin = '1995년 SBS 드라마 〈모래시계〉에서 최민수가 연기한 박태수가 교수형을 당하기 직전 읊조린 대사다. 친구인 검사 강우석(박상원)이 사형을 구형한 뒤 집행을 기다리는 상황에서 나온 말로 설명된다. 2012년 최민수 인터뷰 기사에서도 이 장면이 비교 기준으로 언급될 만큼 오래 회자됐다.',
  usage_note = '중요한 일을 앞두고 긴장한 상황을 과장해서 표현할 때 어울리고, 옛 드라마 명대사를 회고하는 글에도 인용된다. 본인의 사소한 긴장을 비장하게 포장하는 용도로 쓰면 가장 자연스럽다.',
  caution = '원래 사형 장면의 대사라 가볍게 쓰면 죽음을 농담거리로 삼는 인상을 줄 수 있다. 큰 병이나 상을 당한 사람, 중대한 결과를 기다리는 사람에게 장난으로 던지면 무례하게 들릴 수 있으므로 자신의 사소한 긴장을 과장하는 정도로 한정하는 편이 좋다.',
  usage_examples = '[{"situation":"면접을 앞둔 친구와 카톡","text":"나 지금 떨고 있니? 면접 10분 전인데 손이 안 멈춰ㅋㅋ"},{"situation":"직장 메신저에서 발표 직전","text":"곧 임원 보고인데 나, 지금 떨고 있냐... 자료 한 번만 더 봐줘."}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'aqerjbu7'
  and slug = '나-지금-떨고-있니'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

