-- 매끈매끈하다 (x4xec2sx / 매끈매끈하다)
update public.memes set
  description = '프랑스 출신 안무가 카니가 MBC 웹예능 〈카니를 찾아서〉에서 한국어 수업 중 ''매끈매끈하다'', ''울퉁불퉁하다'', ''평평하다'' 같은 형용사를 외우려고 즉석에서 랩과 춤을 붙인 장면이다. 같은 소리를 반복하는 구조라 입에 잘 붙고, 단어 자리에 다른 의성어나 의태어를 넣어 리듬을 유지한 채 바꿔 부르기 쉽다는 점이 유행 요인으로 꼽혔다. 2025년 11월 대학수학능력시험을 며칠 앞두고 퍼지며 ''새 수능 금지곡''이라는 농담과 ''고3은 시청 금지''라는 경고성 댓글이 붙었고, 샤이니 키를 비롯해 투어스, 하츠투하츠, 제로베이스원 등 아이돌이 매끈매끈 챌린지에 참여했다.',
  origin = 'MBC 유튜브 채널의 웹예능 〈카니를 찾아서〉에서 카니가 한국어 형용사를 배우다 즉석으로 만든 랩과 춤이 시작이다. 해당 회차의 정확한 공개일은 열어본 출처에 없지만, 2025년 11월 수능 직전에 커뮤니티와 SNS로 빠르게 퍼졌고 카니가 샤이니 키와 함께 만든 챌린지로 이어졌다.',
  usage_note = '반복 구조를 살려 사물의 질감이나 상태를 가리키는 말을 바꿔 넣는 패러디에 어울리고, 시험철에 머릿속에서 떠나지 않는 노래를 두고 농담할 때도 쓴다. 동작이 쉬워 챌린지 영상으로 따라 하기 좋다.',
  caution = '수능을 앞둔 수험생에게는 집중을 흐트러뜨리는 노래라는 농담이 붙은 밈이라, 시험을 앞둔 사람에게 일부러 들려주거나 영상을 계속 보내는 장난은 짜증을 살 수 있다. 실제 외국인의 한국어 학습 장면에서 나온 것이므로 외국인의 발음을 흉내 내 놀리는 식으로 쓰는 것은 삼가야 한다.',
  usage_examples = '[{"situation":"수능 전날 단톡방","text":"수능 D-1인데 매끈매끈하다가 머리에서 안 떠나... 이거 금지곡 맞네"},{"situation":"숏폼 패러디 댓글","text":"말랑말랑하다 말랑말랑한~ 단어만 바꿔도 되는 구조라 계속 하게 된다ㅋㅋ"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'x4xec2sx'
  and slug = '매끈매끈하다'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

