-- 모시모시 챌린지 (ebs8nb43 / 모시모시-챌린지)
update public.memes set
  description = '일본의 18세 틱톡 크리에이터 사사네(楽音, sasane)의 데뷔곡 ''mosi mosi?''를 배경음악으로 쓰는 숏폼 챌린지다. 전화를 받을 때 하는 인사 ''모시모시''와 상대에게 소리가 들리는지 묻는 전화 통화 같은 후렴이 중심이라, 귀여운 춤을 따라 추거나 손글씨 같은 효과를 넣어 올리는 영상이 많다. 정식 발매 전부터 후렴이 틱톡에서 먼저 퍼졌고, 일본과 한국 틱톡 인기곡 차트에서 동시에 1위에 올랐다는 보도가 있다. 한국에서는 NCT 위시, IVE, 트와이스 미사모 등 아이돌이 같은 곡으로 영상을 올리며 확산됐고, 사사네는 한국어 버전도 냈다.',
  origin = '사사네가 2026년 4월 22일 발매한 데뷔 싱글 ''mosi mosi?''에서 나왔다. 발매 전인 3월에 한 틱톡 이용자가 가사에 맞춘 귀여운 안무를 만들었고, 후렴이 먼저 틱톡에서 화제가 됐다. 5월 초 보도에서는 일본과 한국 틱톡 인기곡 차트에서 동시에 1위를 기록했다고 전했다.',
  usage_note = '귀엽거나 장난스러운 콘셉트의 숏폼, 전화 받는 상황극, 자기소개나 일상 브이로그의 배경음악으로 어울린다. 한국어 버전도 있어 영상 분위기에 맞춰 고를 수 있다.',
  caution = '하나의 공식 안무가 정해진 챌린지가 아니라 이용자가 만든 여러 버전이 섞여 있으므로 특정 동작을 공식이라고 단정하지 않는 것이 좋다. 일본 아티스트의 곡이라 상업 영상이나 광고에 쓸 때는 플랫폼의 음원 사용 범위를 확인해야 한다.',
  usage_examples = '[{"situation":"틱톡 영상 캡션","text":"모시모시? 내 말 들려? 이번 주 챌린지는 이거야"},{"situation":"친구 단톡방","text":"이거 같이 찍자. 전화 받는 콘셉트라 쉬워. 모시모시~"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'ebs8nb43'
  and slug = '모시모시-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

