-- 에픽하이 Love Love Love 챌린지 (g76rc5fs / 에픽하이-Love-Love-Love-챌린지)
update public.memes set
  description = '에픽하이가 2007년에 낸 정규 4집 수록곡 ''Love Love Love''의 가사에 맞춰 손으로 하트를 그리는 동작을 따라 하는 숏폼 챌린지다. 틱톡, 유튜브 쇼츠, 인스타그램 릴스에 영상이 이어 올라오면서 2026년 1월 초 이 곡이 국내 음원 차트를 다시 오르는 현상이 나타났다. 보도에 따르면 멤버 타블로, DJ 투컷, 미쓰라진도 직접 챌린지에 참여했고 이것이 확산에 힘을 보탰다. 1월 중순 보도 기준으로 애플뮤직 코리아 3위, 스포티파이 코리아 9위까지 올랐다고 전해진다. 오래전에 나온 곡이 숏폼 챌린지를 계기로 다시 인기를 얻는 흐름을 보여 주는 대표적인 사례로 언급된다.',
  origin = '곡은 2007년 발매된 에픽하이 정규 4집 ''Remapping the Human Soul''에 실려 있다. 2026년 1월 초 틱톡, 쇼츠, 릴스에서 가사에 맞춰 하트를 그리는 챌린지가 퍼지며 곡이 차트에 다시 올랐다. 챌린지를 가장 먼저 올린 사람과 정확한 시작 시점은 확인한 자료에 나오지 않는다.',
  usage_note = '오래된 명곡을 다시 꺼내 숏폼 영상으로 즐기거나, 세대가 다른 사람과 같은 노래를 함께 따라 할 때 어울린다. 친구들과 하트 동작을 같이 찍어 올리는 식의 가벼운 참여형 콘텐츠에 쓰인다.',
  caution = '특정 시기에 유행한 챌린지라 시간이 지나면 지금 유행하는 것처럼 말하기 어색해진다. 제목에 ''Love''가 들어 있어 이성에게 장난으로 보내면 호감 표시로 오해받을 수 있고, 영상에 다른 사람이 함께 나온다면 올리기 전에 동의를 구하는 것이 좋다.',
  usage_examples = '[{"situation":"친구들 단톡방에서 주말 촬영을 제안할 때","text":"러브러브러브 하트 챌린지 다들 봤지? 이번 주말에 우리도 찍자"},{"situation":"SNS 숏폼 영상 캡션","text":"2007년 노래가 2026년에 또 돌아왔다 #러브러브러브챌린지"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'g76rc5fs'
  and slug = '에픽하이-Love-Love-Love-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

