-- 꿍따리 샤바라 (qusn97eb / 꿍따리-샤바라)
update public.memes set
  description = '1996년에 발매된 클론의 데뷔 앨범 ''Are You Ready?''의 타이틀곡이다. 제목의 ''꿍따리 샤바라''는 뚜렷한 뜻이 없는 의성어에서 따온 주문 같은 말로, 주간한국은 코미디언 이기동의 유행어 ''꿍따리 닥닥 삐약 삐약''에서 착안했다고 전한다. 처음에는 통기타 반주의 단순한 곡이었던 것을 랩과 댄스 중심으로 다시 편곡하면서 지금의 모습이 됐고, 클론의 두 멤버가 비보이 출신이라는 점도 힘 있는 안무와 어울렸다. 가사는 시련과 희망을 담은 건전한 내용으로 소개된다. KBS ''가요톱10''에서 골든컵을 받았고, 대만과 중국에서도 큰 인기를 끌어 한류 초기 사례로 언급된다.',
  origin = '1996년 5월 클론 1집 ''Are You Ready?''로 발매됐다. 주간한국에 따르면 프로듀서 김창환이 녹음 후 두 시간 남짓 만에 타이틀곡으로 낙점했고, 오마이스타는 같은 해 클론이 마이클 잭슨의 첫 내한 공연에서 오프닝 무대에 올라 이 곡을 불렀다고 쓴다.',
  usage_note = '분위기를 띄우는 후렴구나 중독성 강한 후크송을 이야기할 때, 또는 90년대 댄스가요를 다루는 레트로 콘텐츠에서 곡명을 인용한다. 가사가 희망을 말하는 내용이라 응원의 분위기로 인용해도 어색하지 않다.',
  caution = '세대 차가 큰 자리에서는 이 곡을 알고 따라 부를 수 있는 사람이 한정될 수 있다. 멤버 강원래의 사고와 재활 이야기가 곡과 함께 소개되는 일이 많아서, 그 사연을 농담 소재로 삼으면 실제 인물의 아픔을 건드리게 된다. 자료에서는 제목을 ''꿍따리''로 표기한다.',
  usage_examples = '[{"situation":"회식 후 단톡방에서 2차 장소를 정할 때","text":"2차는 노래방! 꿍따리 샤바라 누가 부를래?"},{"situation":"레트로 무대 영상 댓글","text":"이 노래 나오면 다 같이 일어나서 춤추게 됨, 후렴구는 몸이 기억한다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'qusn97eb'
  and slug = '꿍따리-샤바라'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

