-- 백룸 (ruamef66 / 백룸)
update public.memes set
  description = '''백룸''은 현실의 틈으로 떨어지면 끝없이 이어지는 텅 빈 복도와 방에 갇힌다는 설정의 인터넷 괴담이자 공포 콘텐츠 장르다. 누런 벽지와 형광등, 눅눅한 카펫 같은 사무 공간의 이미지가 핵심이며, 사람이 있어야 할 곳이 이상하게 비어 있을 때 느끼는 어긋난 불안감을 다루는 이른바 리미널 스페이스 미학의 대표 사례로 꼽힌다. 처음에는 이미지 한 장과 짧은 글에서 출발했지만 레딧의 괴담 커뮤니티에서 이야기가 덧붙었고, 2022년 이후 영상과 게임으로 퍼지며 세계관이 커졌다. 원본 사진은 2002년 미국 위스콘신주 오시코시의 옛 가구점 내부를 개조하던 때 찍힌 것으로, 출처는 2024년 5월에야 밝혀졌다.',
  origin = '2019년 5월 4chan의 초자연 게시판 /x/에서 한 이용자가 으스스한 이미지를 공유해 달라고 하자 누런 사무실 사진이 올라왔고, 이후 익명의 댓글이 이 공간을 ''백룸''이라 부르며 설정을 덧붙인 것이 시작이다. 2022년 1월 당시 16세였던 케인 파슨스(Kane Pixels)가 1990년대 VHS 영상 형식의 단편을 유튜브에 올리면서 대중화됐다.',
  usage_note = '으스스한 빈 공간이나 끝없이 이어지는 복도 사진, 공포 게임과 영상 소재를 이야기할 때 쓴다. 익숙한 장소가 이상하게 비어 보일 때 ''백룸 같다''고 비유하는 식으로도 쓸 수 있다.',
  caution = '공포와 불안을 주는 콘텐츠라서 어린 사용자나 공포에 민감한 사람에게 갑자기 보내면 불쾌할 수 있다. 백룸 세계관은 여러 창작자가 덧붙인 설정이 많아 하나의 공식 설정처럼 단정하면 틀리기 쉽고, 실제 장소의 사진에 괴담을 붙일 때는 그곳과 사람을 조롱하는 것이 되지 않도록 주의해야 한다.',
  usage_examples = '[{"situation":"친구들 단톡방에 새벽 지하 주차장 사진을 올리며","text":"여기 왜 이렇게 백룸 같냐, 출구 못 찾을 것 같아"},{"situation":"텅 빈 사무실 사진 게시물의 댓글","text":"이거 백룸 입구 아니냐 ㅋㅋ 현실의 틈으로 떨어지면 못 돌아올 듯"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'ruamef66'
  and slug = '백룸'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

