-- Rizz 밈 (ua66cnyx / Rizz-밈)
update public.memes set
  description = '''rizz''(리즈)는 charisma(카리스마)의 가운데 부분에서 나온 것으로 보이는 Z세대 슬랭으로, 스타일과 매력, 특히 이성을 끌어당기는 능력을 뜻한다. ''have rizz''처럼 명사로도 쓰고, ''rizz up''처럼 누군가에게 말을 걸어 호감을 얻거나 꼬신다는 동사로도 쓴다. 2023년 6월 배우 톰 홀랜드가 버즈피드 인터뷰에서 자신은 rizz가 전혀 없고 제한적인 rizz만 있다고 말한 장면이 밈으로 퍼지면서 사용량이 크게 늘었다. 옥스퍼드 대학 출판부는 이 단어를 2023년 올해의 단어로 선정했고, 소셜미디어 언급이 전년 대비 약 15배 늘었다고 밝혔다. 같은 해 후보에는 Swiftie, situationship, prompt가 함께 올랐다.',
  origin = '가디언 보도에 따르면 이 단어는 2022년에 처음 기록됐고 charisma에서 나온 것으로 여겨진다. 세계일보는 트위치 스트리머 카이 세나트가 방송에서 처음 사용했다고 소개한다. 2023년 6월 톰 홀랜드의 인터뷰 장면이 밈이 되며 확산됐고, 같은 해 12월 초 옥스퍼드가 올해의 단어로 발표했다.',
  usage_note = '이성에게 호감을 얻는 말솜씨나 분위기를 이야기할 때 ''쟤는 rizz가 있다'', ''나는 rizz가 없다''처럼 쓴다. 자신이나 친구의 어색한 접근을 농담조로 놀릴 때도 어울린다.',
  caution = '한국어 ''리즈 시절''의 리즈와는 발음이 비슷할 뿐 뜻이 다른 별개의 단어다. 특정인의 연애 능력이나 매력을 평가하는 말이라서, 본인이 없는 자리에서 점수를 매기듯 쓰면 무례하게 들릴 수 있다.',
  usage_examples = '[{"situation":"친구들 단톡방에서 소개팅 후기를 들을 때","text":"첫 만남에서 번호를 받아왔다고? rizz 미쳤네"},{"situation":"SNS 댓글","text":"톰 홀랜드도 rizz가 없다는데 나는 말해 뭐해"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'ua66cnyx'
  and slug = 'Rizz-밈'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

