-- 남쟈 없냐 남쟈 (j7fqfjm4 / 남쟈-없냐-남쟈)
update public.memes set
  description = '''남자 없냐 남자''를 혀 짧은 듯한 말투로 바꾼 표현으로, 소개팅 상대를 구해 달라고 졸라 대는 친한 언니의 말투를 흉내 내는 밈이다. 원문에는 ''공기업 남쟈 소개시켜줘야쥬''처럼 조건까지 붙은 요구가 담겼고, 끝에 🥴 이모지를 곁들이는 경우가 많다. 이후 ''○○ 없냐 ○○ 소개시켜줘야쥬''라는 틀에 원하는 대상을 바꿔 넣는 방식으로 퍼졌다. 휴가를 바라는 직장인이 ''연챠 없냐 연챠''로 바꿔 쓴 변형이 대표적이고, 뷰티 브랜드가 홍보 문구에 빌려 쓰거나 방송 클립 썸네일에 쓰인 사례도 보도됐다.',
  origin = '2026년 5월 무렵 온라인 커뮤니티에 올라온, 친한 언니와 나눈 대화 캡처에서 시작됐다. 남자를 소개해 달라고 조르는 말투가 웃음 포인트였고 X에서 큰 반응을 얻으며 퍼졌다. 한 밈 정리 글은 리트윗 8천 회, 좋아요 1.1만 개를 기록했다고 전한다. 처음 올라온 커뮤니티 이름은 확인한 출처에 나오지 않는다.',
  usage_note = '친구에게 무언가를 능청스럽게 졸라 대거나 바라는 것을 장난스럽게 말할 때 어울린다. ''○○ 없냐 ○○'' 틀에 연차, 맛집, 월급처럼 원하는 대상을 넣고 끝에 ''소개시켜줘야쥬''를 붙이면 된다.',
  caution = '원래 문장이 이성 소개를 졸라 대는 사람을 놀리는 말투라서, 연애나 결혼 문제로 부담을 느끼는 사람에게 쓰면 놀림이나 압박으로 들릴 수 있다. 친하지 않은 상대나 격식을 갖춰야 하는 자리에서는 가볍게 쓰기 어렵고, 유행이 지나면 어색해질 수 있다.',
  usage_examples = '[{"situation":"직장 동료들과 쓰는 단톡방, 월요일 아침","text":"휴가 없냐 휴가 유급휴가 소개시켜줘야쥬 🥴"},{"situation":"SNS 캡션, 점심 먹을 곳을 찾을 때","text":"맛집 없냐 맛집 회사 근처 맛집 소개시켜줘야쥬 🥴"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'j7fqfjm4'
  and slug = '남쟈-없냐-남쟈'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

