-- 욜로 (ssz92m8b / 욜로)
update public.memes set
  description = '''You Only Live Once''의 머리글자로, 인생은 한 번뿐이니 미래를 위해 아끼기보다 지금의 행복과 경험에 쓰자는 태도를 뜻한다. 한국에서는 구호를 넘어 소비 성향을 가리키는 말로 자리 잡아, 전세 보증금을 털어 세계 여행을 떠나거나 취미와 자기 시간에 돈을 쓰는 사람을 ''욜로족''이라 불렀다. 금융·유통·여행 업계가 관련 상품을 내놓았고 방송에서도 욜로를 내세운 예능이 늘었다. 다만 한국에서는 미래에 대한 불안과 체념이 섞인 말로 받아들여지는 면도 있어, 소소한 지출을 즐기는 ''탕진잼'' 같은 파생 표현과 함께 언급됐다.',
  origin = '영어 표현 YOLO는 2011년 캐나다 래퍼 드레이크의 곡 ''The Motto''로 널리 알려졌다. 한국에서는 2016년 3월 tvN <꽃보다 청춘> 아프리카 편에서 출연자가 이 말을 접하는 장면이 나오며 알려졌고, 2017년에는 <트렌드 코리아 2017> 등이 주요 트렌드로 꼽으면서 소비 키워드로 확산됐다.',
  usage_note = '한 번뿐인 인생이라며 여행, 취미, 경험에 과감히 돈이나 시간을 쓰는 선택을 이야기할 때 쓴다. ''욜로족'', ''욜로 소비''처럼 명사 앞에 붙이거나, 큰 결심을 가볍게 합리화하며 ''욜로!''라고 외치는 식으로도 쓴다.',
  caution = '재정 계획 없이 소비를 정당화하는 핑계로 들릴 수 있어, 저축이나 빚 문제로 고민하는 사람에게 쓰면 무책임하다는 비판처럼 느껴질 수 있다. 한국에서는 불안과 체념을 포장한 말이라는 시각도 있으므로, 사정을 모른 채 상대를 ''욜로족''이라 부르면 실례가 될 수 있다.',
  usage_examples = '[{"situation":"친구들 단톡방, 휴가를 당겨 해외여행을 가기로 했을 때","text":"휴가 땡겨서 오사카 간다. 인생 한 번뿐이잖아 ㅋㅋ 욜로!"},{"situation":"SNS 캡션, 취미에 쓴 돈을 자랑하며","text":"이번 달 취미비 한도 초과. 욜로라고 우겨 본다. 다음 달은 아껴 쓰자"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'ssz92m8b'
  and slug = '욜로'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

