-- 셋로그 (g43hqn23 / 셋로그)
update public.memes set
  description = '친구들이 각자 찍은 아주 짧은 영상을 하루치 분할 화면 영상으로 묶어 주는 앱 ''셋로그(SETLOG)''와, 이를 이용해 일상을 공유하는 유행을 가리킨다. 방을 만들고 초대 코드를 보내면 친구들이 들어오고, 몇 시간 간격으로 알림이 오면 그 순간의 모습을 짧게 찍어 올린다. 하루가 끝나면 영상들이 자동으로 분할 화면 브이로그로 만들어지며 편집이나 자막, 음악이 필요 없다. 꾸미지 않은 일상을 부담 없이 나눌 수 있고 알림을 건너뛰어도 된다는 점이 인기 요인으로 꼽혔다.',
  origin = '한국 스타트업 뉴챗이 만든 앱으로, 보도에 따르면 2025년 12월 아이폰용으로 먼저 나오고 2026년 4월 23일 안드로이드 버전이 나왔다. 2026년 4월 초 애플 앱스토어 소셜 네트워킹 부문 1위에 오르며 Z세대 사이에서 화제가 됐고, 안드로이드 베타 출시 5일 만에 구글 플레이 누적 다운로드가 50만을 넘었다고 전해진다.',
  usage_note = '친구나 가족과 하루를 가볍게 기록하고 싶을 때, 또는 꾸미지 않은 일상을 공유하는 분위기를 이야기할 때 쓴다. ''오늘 셋로그 방 열자''처럼 앱 이름을 그대로 넣어 함께 하자고 제안하는 식으로 쓸 수 있다.',
  caution = '자주 찍는 영상에 위치와 생활 패턴이 드러날 수 있어 사생활 노출에 주의해야 한다는 지적이 있다. 영상을 올리지 않은 칸이 비어 보이면 또래 압박으로 느껴질 수 있다는 우려도 있다. 앱의 인기는 시기에 따라 달라지므로 지금도 같은 열기라고 단정하기는 어렵다.',
  usage_examples = '[{"situation":"친구들 단톡방, 새 방을 만들며","text":"셋로그 방 열었어. 링크로 들어와서 알림 오면 바로 찍자 ㅋㅋ"},{"situation":"인스타그램 댓글, 친구가 하루치 영상을 올렸을 때","text":"셋로그로 모아 놓으니까 우리 하루가 한 편짜리 영화 같다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'g43hqn23'
  and slug = '셋로그'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

