-- 트리피 트로피(Trippi Troppi) (w8qjvg87 / 트리피-트로피(Trippi-Troppi))
update public.memes set
  description = 'AI로 만든 이탈리안 브레인롯 밈 가운데 하나로, 말이 되지 않는 이탈리아식 운율의 음성을 붙인 짧은 영상이다. 영문 표기는 Trippi Troppi이며 비슷한 이름의 트룰리메로 트룰리치나(Trulimero Trulichina)와 한 항목으로 묶여 다뤄지기도 한다. 소리와 함께 쓰이는 캐릭터는 물고기 머리를 한 털북숭이 생물, 또는 고양이와 새우를 섞은 모습으로 소개되는 등 자료마다 설명이 다르다. 트랄랄레로 트랄랄라, 붐바르딜로 크로코딜로 같은 다른 브레인롯 캐릭터와 함께 순위를 매기거나 대결시키는 영상으로도 만들어졌다.',
  origin = 'Know Your Meme에 따르면 ''트리피 트로피'' 음원을 쓴 가장 이른 영상으로 확인된 것은 2025년 2월 18일 틱톡 게시물이다. 2025년 3월 말에서 4월 초 사이 틱톡과 유튜브에서 크게 유행했고, 한국 트렌드 칼럼에서도 이탈리안 브레인롯 캐릭터로 소개됐다. 원본 AI 이미지를 만든 사람은 확인되지 않는다.',
  usage_note = '뜻을 따지기보다 리듬과 어감 자체를 즐기는 브레인롯 밈이라, 친구끼리 말도 안 되는 이탈리아식 이름을 주고받으며 놀 때 어울린다. 다른 브레인롯 캐릭터와 묶어 누가 더 센지 겨루는 가벼운 비교 놀이로 쓰기도 한다.',
  caution = '맥락 없이 반복하면 뜻을 모르는 사람에게는 소음이나 헛소리로 들리고, 브레인롯 문화에 익숙하지 않은 부모님이나 상사와는 소통이 되지 않는다. 같은 이름이 가리키는 캐릭터가 자료마다 달라 정확한 설정을 단정해서 설명하면 틀릴 수 있다.',
  usage_examples = '[{"situation":"친구들 단톡방, 회의가 길어진 날","text":"회의 두 시간 하고 나니까 뇌가 트리피 트로피 됐다 ㅋㅋ"},{"situation":"영상 댓글","text":"이 영상 보고 나서 하루 종일 트리피 트로피만 맴돈다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'w8qjvg87'
  and slug = '트리피-트로피(Trippi-Troppi)'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

