-- 조선왕조실톡 (n2gn98nq / 조선왕조실톡)
update public.memes set
  description = '조선왕조실록 등 사서의 기록을 모바일 메신저 대화 형식으로 옮긴 웹툰으로, 왕과 신하가 단체 대화방에서 이야기하듯 역사 속 사건을 현대 말투로 풀어낸다. 조선시대에도 스마트폰이 있었다는 가정을 깔고, 임금이 SNS로 일을 지시하거나 관료들이 단체 대화방에서 뒷말을 나누는 장면이 나온다. 작가는 실록 자체가 대화를 기록한 글이어서 거기에 인물의 성격과 상황을 덧붙여 재미를 더했을 뿐이라며, 역사 만화라기보다 일상 만화에 가깝다고 설명했다. 2015년 3월 작가가 JTBC <썰전>에 나온 뒤 실시간 검색어에 올랐고, 같은 해 7월에는 MBC 에브리원 <웹툰히어로-툰드라쇼>의 한 코너로 드라마화됐다.',
  origin = '무적핑크 작가가 2014년 12월 9일부터 네이버 웹툰에서 연재를 시작했고 매주 수요일과 일요일에 올라왔다. 2015년 3월 JTBC <썰전> 출연으로 화제가 됐고, 위키백과는 2019년 6월 기준 364화 분량이라고 적고 있다.',
  usage_note = '역사 속 사건이나 인물을 현대 메신저 말투로 풀어 소개하거나 패러디할 때 참고 사례로 언급할 수 있다. 딱딱한 역사를 가볍게 접하게 한다는 취지로 이야기할 때 어울린다.',
  caution = '작가가 실록과 야사를 소재로 각색해 재미를 더한 작품이라, 내용을 실제 역사 기록 그대로로 받아들이면 곤란하다. 시험 공부나 보고서의 근거로 인용하기보다 흥미를 끄는 입문용으로만 쓰는 편이 안전하다. 연재 상태와 분량은 자료마다 달라 최신 여부는 따로 확인해야 한다.',
  usage_examples = '[{"situation":"친구와의 대화, 역사 수업이 끝난 뒤","text":"조선왕조실톡 보고 나서부터 임금님 단톡방 상상하는 버릇 생겼다 ㅋㅋ"},{"situation":"SNS 캡션","text":"실록을 카톡으로 읽으니까 이렇게 쉽다. 조선왕조실톡 정주행 중"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'n2gn98nq'
  and slug = '조선왕조실톡'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

