-- 엄마 동결건조 (68jvjktr / 엄마-동결건조)
update public.memes set
  description = '식품을 얼려 수분을 제거해 오래 보관하는 동결건조에서 따온 표현으로, 소중한 사람을 지금 모습 그대로 오래 곁에 두고 싶다는 마음을 장난스럽게 말한다. 가장 널리 알려진 형태가 ''엄마 동결건조''이며, 딸이 엄마에게 이 이미지를 보내고 엄마가 뜻을 되묻는 장면 자체가 웃음 포인트가 됐다. ''엄마'' 자리에 아이돌이나 다른 소중한 대상을 넣어 전성기 모습을 간직하고 싶다는 뜻으로도 쓴다. 엄마를 유난히 좋아하는 자녀를 가리키는 ''엄미새''와 함께 다뤄지며, 엄마의 나이 듦을 무겁게만 받아들이고 싶지 않은 마음을 돌려 말하는 애정 표현으로 해석된다.',
  origin = '한 트렌드 뉴스레터(2026년 2월 25일자)에 따르면 지난 9월 X의 한 이용자가 처음 쓴 표현이 천천히 퍼지다가, 설 연휴 무렵 부모님 건강을 이야기하는 게시물과 함께 널리 알려졌고 이후 인스타그램 릴스와 스레드로 번졌다. 2026년 5월 지역 일간지 기사도 SNS 중심으로 퍼진 엄마 향한 애정 밈으로 다뤘지만, 최초 게시자와 정확한 시점은 이 기사에 나오지 않는다.',
  usage_note = '엄마나 가족에게 쑥스러운 애정을 가볍게 돌려 표현할 때 쓴다. 가족 대화방에 이미지를 보내거나 ''우리 엄마 동결건조 시켜야 함''처럼 댓글을 달 수 있고, 좋아하는 사람의 지금 모습을 간직하고 싶을 때도 쓴다.',
  caution = '부모 세대에게는 낯선 표현이라 설명 없이 보내면 당황하거나 식품을 가리키는 말로 오해할 수 있다. 나이 듦이나 건강을 떠올리게 하는 말이기도 해서, 부모님 몸이 편치 않거나 그런 이야기에 예민한 상황에서는 부적절하게 느껴질 수 있으니 분위기를 살펴 쓰는 편이 좋다.',
  usage_examples = '[{"situation":"가족 단톡방, 엄마 사진을 올리며","text":"엄마 오늘 너무 예뻐서 동결건조 시키고 싶다. 뜻은 이 모습 그대로 오래 있어 달라는 거야"},{"situation":"SNS 댓글, 아이돌 전성기 영상 아래","text":"이 시절 모습 그대로 동결건조 해 주세요 제발"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '68jvjktr'
  and slug = '엄마-동결건조'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

