-- 박지성 두 개의 심장 (aqv9he5e / 박지성-두-개의-심장)
update public.memes set
  description = '맨체스터 유나이티드에서 활약한 박지성의 별명으로, 경기 내내 지치지 않고 가장 많이 뛰는 활동량을 심장이 두 개인 사람에 빗댄 표현이다. 산소탱크, 세 개의 폐를 가진 사나이, 오토바이 같은 별명과 같은 계열로 소개되며, 이 별명들은 모두 누구보다 많이 끝까지 포기하지 않고 뛰는 모습에서 비롯됐다고 설명된다. 현대자동차 브랜드 저널은 이 활동량으로 팀에 공헌해 퍼거슨 감독에게 헌신적인 선수라는 평을 받았다고 소개한다. 자료에 따라 ''2개 심장''처럼 표기가 조금씩 달라진다.',
  origin = '맨체스터 유나이티드 시절 박지성의 쉼 없는 활동량을 두고 붙은 별명으로, 산소탱크 등 같은 계열의 별명과 함께 소개된다. 누가 언제 처음 불렀는지는 확인한 출처에 나오지 않는다.',
  usage_note = '박지성의 체력과 활동량을 이야기할 때, 또는 쉬지 않고 뛰어다니는 사람을 농담조로 칭찬할 때 쓸 수 있다. 경기 내내 지치지 않는다는 뜻이라 체력과 헌신을 칭찬하는 맥락에 맞는다.',
  caution = '비유적인 별명이므로 실제 신체 특징이 있는 것처럼 설명하면 사실과 다르다. 심박수 같은 구체적 수치는 이번에 확인한 출처에서 찾을 수 없었다. 다른 사람에게 쓸 때 상대가 지쳤거나 쉬어야 하는 상황이면 쉬지 말고 뛰라는 압박으로 들릴 수 있다.',
  usage_examples = '[{"situation":"축구 동호회 단톡방, 풀타임을 뛴 친구에게","text":"오늘도 90분 내내 뛰네. 심장이 두 개인 박지성 같다"},{"situation":"직장 메신저, 외근을 연달아 마친 동료에게","text":"세 군데를 다 돌고 오셨다고요? 심장이 두 개세요?"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'aqv9he5e'
  and slug = '박지성-두-개의-심장'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

