-- SKY 캐슬 쓰앵님 (64u6wftq / SKY-캐슬-쓰앵님)
update public.memes set
  description = 'JTBC 드라마 ''SKY 캐슬''에서 염정아가 연기한 한서진이 입시 코디네이터 김주영(김서형)을 ''선생님''이라고 부르는 발음이 ''쓰앵님''처럼 들린다는 데서 나온 유행어다. 급하게 말하는 ''선생님''의 어감을 흉내 내는 방식으로 쓰이며, 같은 드라마의 ''아갈머리'' 대사와 함께 패러디와 성대모사의 소재가 됐다. 염정아 본인은 자신이 ''선생님''이라고 말한 줄 알았고, 방송 뒤 이 표현이 퍼지자 젊은 층이 쓰는 신조어인 줄 알았다고 밝혔다. 나중에야 빠르게 말하는 ''선생님''이 그렇게 들린다는 걸 알게 됐다는 것이다.',
  origin = '2018년 말 방송을 시작해 2019년 2월 1일 종영한 JTBC ''SKY 캐슬''에서 한서진이 김주영을 ''선생님''이라 부르는 대사가 시청자 귀에 ''쓰앵님''으로 들려 유행어가 됐다. 염정아는 2019년 2월 인터뷰에서 이 말과 ''아갈머리''가 유행할 줄 몰랐다고 말했다.',
  usage_note = '상대에게 과장되게 부탁하거나 아부하는 상황을 장난스럽게 흉내 낼 때 쓴다. ''선생님''을 ''쓰앵님''으로 바꿔 부르며 급하고 애절한 말투를 덧붙이면 드라마 속 장면이 연상된다.',
  caution = '실제 선생님이나 교수를 이 말투로 부르면 놀리거나 비꼬는 것으로 들려 무례할 수 있다. 입시 경쟁을 다룬 드라마에서 나온 말이라 수험생이나 학부모가 민감한 상황에서는 농담으로 받아들여지지 않을 수 있다. 특정 배우의 발음을 조롱하는 방향으로 쓰는 것도 피하는 편이 좋다.',
  usage_examples = '[{"situation":"대학 단톡방, 과제 노트를 빌리고 싶을 때","text":"쓰앵님~ 필기 한 번만 보여주세요 ㅠㅠ"},{"situation":"직장 메신저, 동료에게 마감 도움을 청하며","text":"쓰앵님… 이번 한 번만 검토 부탁드립니다 제발요"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '64u6wftq'
  and slug = 'SKY-캐슬-쓰앵님'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

