-- 소녀시대 Gee 개다리춤 (srrux63v / 소녀시대-Gee-개다리춤)
update public.memes set
  description = '소녀시대의 ''Gee''(2009년 1월 발매)에 맞춰 추는 동작을 가리키는 말이다. 2009년 초 보도는 곡의 후반부에 선보인 개다리춤이 또 한 번의 열풍을 일으킬 것이라고 내다봤다. 곡이 큰 인기를 얻으면서 멤버들이 입은 컬러 스키니진도 함께 유행해 ''소시지(소녀시대 Gee) 스타일''이라는 말이 생겼고, 온라인 쇼핑몰에서 컬러 스키니진이 하루 2천 벌가량 팔렸다는 보도가 나왔다. ''Gee''는 뮤직뱅크 9주 연속 1위 같은 기록도 세웠다. 그래서 개다리춤은 단순한 안무 이름을 넘어 2009년 걸그룹 열풍과 그 시절 패션을 함께 떠올리게 하는 말로 쓰인다.',
  origin = '2009년 1월 5일 소녀시대의 미니앨범 ''Gee''가 발매되었고, 같은 달 10일자 기사는 이 곡 무대의 후반부에 선보인 개다리춤이 팬들의 눈길을 끌었다고 전했다. 2월에는 컬러 스키니진 판매가 늘며 ''소시지 스타일''이 화제가 되었다. 개다리춤이 처음 공개된 정확한 방송은 확인하지 못했다.',
  usage_note = '2009년 전후의 걸그룹 열풍이나 그 시절 패션을 회상하는 맥락에서 가볍게 꺼내기 좋다. 곡 이름 ''Gee''를 함께 붙이면 어떤 춤인지 바로 전해진다.',
  caution = '특정 멤버나 연령대를 놀리는 용도로 쓰면 무례해질 수 있다. 2009년 당시를 모르는 사람에게는 어떤 춤인지 잘 전해지지 않으므로 곡 이름을 같이 밝히는 편이 안전하다.',
  usage_examples = '[{"situation":"단톡방, 송년회 장기자랑 준비","text":"이번 장기자랑은 소녀시대 Gee 개다리춤으로 가자ㅋㅋ"},{"situation":"SNS 캡션, 옛날 사진","text":"스키니진에 개다리춤까지, 2009년 감성 그대로네"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'srrux63v'
  and slug = '소녀시대-Gee-개다리춤'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

