-- 피식대학 한사랑산악회 (segffxbc / 피식대학-한사랑산악회)
update public.memes set
  description = '유튜브 채널 ''피식대학''의 콩트 코너로, 중년 남성들의 산악회 모임을 실제처럼 흉내 낸다. 월간산은 ''진짜 산악회가 아니다''라고 소개하며, 실제 등산 모임에서 나올 법한 일상 대화와 배 위까지 끌어올린 바지, 어색한 손가락 하트 같은 디테일을 재현한다고 설명했다. 김영남(회장), 이택조(부회장), 배용길(LP바 사장), 정광용(물리 교사)이라는 네 캐릭터를 김민수, 이창호, 이용주, 정재형이 맡는다. 말끝마다 열정을 외치는 ''열쩡!'' 구호가 유행어가 되었고, 월간산은 시청자의 약 80%가 20~30대라고 전했다. 그래서 이 이름은 중년 아저씨 말투나 분위기를 장난스럽게 따라 할 때 인용된다.',
  origin = '유튜브 채널 피식대학의 콩트로, 2021년 6~7월 마리끌레르 코리아와 월간산 등이 잇따라 다루며 화제가 되었다. 월간산(2021년 7월호)은 영상당 평균 조회수가 약 100만이라고 전했고, 마리끌레르는 스눕 독이 영상을 인스타그램에 올린 일을 소개했다. 코너가 처음 공개된 정확한 시점은 확인하지 못했다.',
  usage_note = '중년 모임이나 직장 선배의 말투를 애정 어린 농담으로 흉내 낼 때 어울린다. ''열쩡!'' 같은 구호를 단톡방에서 의욕을 북돋는 장난으로 쓰는 식이다.',
  caution = '특정 연령대나 실제 중년 남성을 조롱하는 말투로 쓰면 불쾌감을 줄 수 있다. 콩트 속 캐릭터 설정이므로 실제 산악회나 등산객 전반을 비꼬는 뜻으로 넓혀 쓰지 않는 편이 좋다.',
  usage_examples = '[{"situation":"단톡방, 주말 등산 약속","text":"이번 주말 산행 간다! 다들 열쩡으로 가자~"},{"situation":"SNS 캡션, 등산 인증샷","text":"배까지 끌어올린 등산바지 입으니 나도 한사랑산악회 입문 완료"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'segffxbc'
  and slug = '피식대학-한사랑산악회'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

