-- 간 때문이야 (zhntapsm / 간-때문이야)
update public.memes set
  description = '대웅제약 간 기능 개선제 ''우루사'' 광고에서 축구선수 차두리가 부른 CM송의 핵심 가사다. 차두리는 2010년 12월 우루사 광고 모델로 나섰고, 한국어 위키백과는 그가 부른 CM송 ''간 때문이야''가 중독성 있는 가사로 큰 화제를 모았다고 적는다. 광고는 젊은 소비자층의 호응을 얻어 한국CM전략연구소 조사에서 광고 호감도 2위에 올랐고, 2011년 1월 우루사 일반의약품 매출이 전년 대비 60% 이상 늘었다고 보도되었다. 이후 피곤하거나 컨디션이 나쁠 때 그 원인을 장난스럽게 ''간 때문''으로 돌리는 말놀이로 쓰인다. 위키백과의 광고 모델 목록에는 차두리가 2023~2024년에도 올라 있다.',
  origin = '2010년 12월 차두리가 우루사 광고 모델로 발탁되어 ''간 때문이야'' 노래가 담긴 광고가 방송되었고, 2011년 2월 26일자 데일리팜 기사는 이 광고가 젊은 층의 호응을 얻었다고 전했다. 한국어 위키백과는 이 노래가 가사의 중독성 때문에 화제가 되었다고 적는다. 곡의 제작 경위와 원곡 여부는 확인하지 못했다.',
  usage_note = '야근 뒤 피곤하거나 컨디션이 안 좋을 때 장난스럽게 ''다 간 때문이야''라고 돌려 말하는 상황에 어울린다. 직장 동료나 친구와의 가벼운 대화에서 분위기를 풀기 좋다.',
  caution = '원래 의약품 광고에서 나온 말이라 실제 건강 문제를 가볍게 ''간 때문''이라고 넘기면 오해를 줄 수 있다. 몸 상태가 계속 나쁘다면 농담으로 넘기지 말고 병원 진료를 받는 편이 낫다.',
  usage_examples = '[{"situation":"직장 메신저, 월요일 아침","text":"오늘 왜 이렇게 피곤하지... 간 때문이야~ 간 때문이야~"},{"situation":"단톡방, 술 마신 다음 날","text":"어제 술 마셨더니 아침부터 비실비실. 다 간 때문이야ㅋㅋ"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'zhntapsm'
  and slug = '간-때문이야'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

