-- 컴백홈 (xgzqteb3 / 컴백홈)
update public.memes set
  description = '서태지와 아이들 4집 타이틀곡 ''컴백홈''과 그 시기의 힙합 스타일을 가리킨다. 갱스터 랩 장르의 곡으로, 서태지가 쓴 스톰(STORM) 브랜드 비니와 고글, 헐렁한 스노보드룩이 곡과 어우러져 선풍적인 인기를 끌었다고 한스경제 칼럼은 설명한다. 보그 코리아는 이 곡이 미국의 랩 문화와 패션을 한국에 대중적으로 퍼뜨렸다고 평했다. 한편 스타일 모방이 지나치다는 비판도 있었다. 이런 평가가 겹치면서 ''컴백홈''은 1990년대 중반의 힙합 패션과 서태지 시대의 문화적 영향력을 함께 떠올리게 하는 말이 되었다.',
  origin = '1995년 10월 5일 서태지와 아이들 4집의 곡으로 발표되었고, 같은 해 11월부터 12월 초까지 주간 음악 프로그램에서 11차례 1위를 했다. 서태지와 아이들은 이듬해 1월 활동 중단을 선언했다. 방송 특집 등 구체적인 첫 무대는 확인하지 못했다.',
  usage_note = '1990년대 힙합 패션이나 서태지와 아이들 시절을 회상할 때, 헐렁한 바지와 비니·고글 스타일을 가리키는 말로 어울린다.',
  caution = '특정 세대에게 익숙한 문화 코드라 젊은 세대에게는 전달이 안 될 수 있다. 곡이나 가수에 대한 평가는 호불호가 갈리므로 단정적인 표현은 피하는 편이 좋다.',
  usage_examples = '[{"situation":"단톡방, 친구의 코디를 보고","text":"비니에 고글까지 쓰고 왔네, 완전 컴백홈 때 서태지 같다ㅋㅋ"},{"situation":"SNS 캡션, 겨울 스노보드룩","text":"헐렁한 바지랑 스노보드룩, 컴백홈 시절 감성 그대로"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'xgzqteb3'
  and slug = '컴백홈'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

