-- 이대호 조선의 4번타자 (etesjj5w / 이대호-조선의-4번타자)
update public.memes set
  description = '롯데 자이언츠 등에서 4번 타자로 활약한 이대호를 부르는 별명이다. 국가대표 4번 타자로 큰 경기에서 결정적인 타점을 올릴 때 특히 자주 불렸다. OSEN은 2015 프리미어12 준결승 일본전에서 이대호가 역전 2타점 적시타를 치며 이 별명을 굳혔다고 전했다. 이후 별명은 그의 대명사가 되어, 2019년 데일리안은 이를 롯데 중심타자 이대호를 대표하는 수식어라고 소개했고, 2022년 10월 은퇴 경기에서는 래리 서튼 감독이 별명이 ''조선의 4번 타자'' 아니냐며 그를 4번에 기용했다. 한국 야구를 대표하는 4번 타자라는 자부심 섞인 농담으로 쓰인다.',
  origin = '정확히 누가 언제 처음 붙였는지는 확인되지 않는다. OSEN은 2015년 프리미어12 준결승 일본전의 역전 적시타로 별명을 굳혔다고 썼고, 2017년 3월 데일리안 기사에서는 이미 이대호를 소개하는 말로 쓰이고 있다.',
  usage_note = '이대호가 중요한 순간에 타점을 올리거나 믿음직한 4번 타자를 칭찬할 때 ''역시 조선의 4번타자''처럼 붙이기 좋다. 야구 커뮤니티 댓글이나 중계 반응에서 자연스럽다.',
  caution = '선수 개인을 가리키는 별명이라 다른 선수나 일반인에게 붙이면 맥락이 어긋난다. ''조선''이라는 표현이 낯설게 들릴 수 있어 격식 있는 자리나 야구를 모르는 사람 앞에서는 설명이 필요하다.',
  usage_examples = '[{"situation":"야구 커뮤니티 댓글","text":"역전 적시타 보소, 역시 조선의 4번타자다"},{"situation":"단톡방, 야구 중계를 보며","text":"방금 홈런 봤냐ㅋㅋ 조선의 4번타자 여전하네"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'etesjj5w'
  and slug = '이대호-조선의-4번타자'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

