-- 마시마로 (jt6zznzd / 마시마로)
update public.memes set
  description = '김재인이 만든 토끼 캐릭터로 ''엽기토끼''라고도 불린다. 대사 없는 플래시 애니메이션으로 인터넷에 처음 선보였고, 큰 눈과 긍정적인 태도가 캐릭터의 조건이라 여기던 관행과 달리 가느다란 눈에 시니컬한 성격이라 여러 감독이 외면했다고 알려져 있다. 화장실 유머를 자주 쓰고 머리에 뚫어뻥이 꽂힌 모습으로 그려지곤 한다. 2001년 5월 경향신문은 엽기토끼 시리즈가 전국적 화제가 되어 인형으로 팔리고 있다고 보도했고, 2003년 씨네21은 마시마로가 전년도 대한민국 캐릭터 대상을 받았으며 네티즌 온라인 설문에서 뿌까에 이어 2위를 했다고 전했다.',
  origin = '김재인이 만든 플래시 애니메이션이 인터넷 만화 사이트에서 인기를 얻으며 시작되었다. 영문 위키백과는 2000년에 등장한 캐릭터로 분류하지만 최초 공개일은 확인하지 못했다. 2001년 5월 경향신문은 엽기토끼 시리즈가 전국적 화제가 되었고 인형으로 판매된다고 보도했다.',
  usage_note = '귀엽지 않은 표정이나 시니컬한 무표정을 가리킬 때, 또는 2000년대 초 인터넷 문화를 회고할 때 쓰기 좋다. ''표정이 마시마로 같다''처럼 장난스럽게 쓴다.',
  caution = '2000년대 초반 캐릭터라 젊은 세대에게는 낯설 수 있다. 상대의 얼굴이나 표정을 이 캐릭터에 빗대면 외모 놀림으로 받아들여질 수 있으니 친한 사이에서만 쓰는 편이 좋다.',
  usage_examples = '[{"situation":"단톡방, 월요일 아침","text":"출근길 내 표정 거울로 봤는데 마시마로 같더라ㅋㅋ"},{"situation":"SNS 캡션, 추억의 물건","text":"서랍에서 엽기토끼 마시마로 인형 발견! 2000년대 추억 소환"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'jt6zznzd'
  and slug = '마시마로'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

