-- Be the Reds 티셔츠 (skhdpv3y / Be-the-Reds-티셔츠)
update public.memes set
  description = '2002 한일 월드컵 때 붉은악마 응원단이 입던 붉은 티셔츠에 새긴 문구 ''Be the Reds!''를 가리킨다. 경향신문에 따르면 디자인은 붉은악마 측 의뢰로 2001년 4월에 시작되었고, 대전의 디자인 업체 네오니아의 박영철 대표가 만들었다. 글자 속 붉은 ''R''은 숫자 12를 형상화해 응원단이 ''12번째 선수''임을 뜻했고, 월드컵 기간에 티셔츠가 2천만 장 넘게 팔린 것으로 추산되었다. 훗날 티셔츠를 입은 모델 사진을 올린 사진업자가 저작권 침해로 기소된 사건에서 서울서부지법은 무죄를 선고하며, 도안의 가치가 국민의 집단적 응원에서 나왔으므로 자유 이용 영역에 가깝다고 판단했다.',
  origin = '붉은악마의 의뢰를 받은 박영철이 2001년 4월부터 디자인했고, 2002년 월드컵 기간에 거리응원 복장으로 널리 퍼졌다. 2002년 7월 4일자 경향신문은 이 티셔츠가 월드컵 기간 2천만 장 이상 팔린 것으로 추산된다고 전했다. 박영철은 저작권심의조정위원회가 자신의 저작권을 인정했다고 밝혔다.',
  usage_note = '2002 월드컵의 열기나 거리응원을 회상하는 글에서 인용하기 좋다. 대표팀 경기 날 단체로 붉은 옷을 맞춰 입자고 할 때도 어울린다.',
  caution = '저작권을 둘러싼 소송이 있었던 문구라 상품을 만들어 팔려면 권리 관계를 따로 확인해야 한다. 응원 문구이므로 다른 팀이나 상대 국가를 비하하는 용도로 쓰면 곤란하다.',
  usage_examples = '[{"situation":"단톡방, 대표팀 경기 날","text":"이번 경기 날은 다 같이 Be the Reds 티셔츠 입고 모이자"},{"situation":"SNS 캡션, 옛날 옷 정리","text":"서랍에서 2002년 Be the Reds 티셔츠 발견, 그날의 함성이 들리는 듯"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'skhdpv3y'
  and slug = 'Be-the-Reds-티셔츠'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

