-- 싸이 - 챔피언 (jjuvahfy / 싸이---챔피언)
update public.memes set
  description = '싸이가 2002년 9월 발표한 3집의 타이틀곡으로, 월드컵 거리응원에서 본 사람들이 신나게 풀어지는 분위기를 곡에 옮긴 댄스곡이다. 빠른 박자의 일렉트로닉 반주 위에 응원하듯 외치는 후렴이 이어져 응원전, 체육대회, 회식 자리에서 분위기를 띄우는 곡으로 자리 잡았다. 해외 평론에서는 해럴드 팔터마이어의 ''Axel F''를 크게 끌어다 쓴 곡이라고 평했다. 당시 방송 활동이 막혀 있던 싸이에게는 복귀의 발판이 된 곡이기도 하고, 2014년 월드컵 응원 무대에서도 싸이가 직접 이 곡을 불렀다. 밈에서는 ''챔피언급 텐션''처럼 한껏 신나고 들뜬 분위기를 가리키는 말로 쓰인다.',
  origin = '싸이는 한일월드컵 때 전 국민과 붉은악마의 응원을 보며 영감을 받아 만든 곡이라고 2014년 무대에서 밝혔다. 곡은 2002년 9월 19일 3집과 함께 나왔으므로 월드컵 기간에 히트한 곡은 아니다. 당시 방송 정지 상태였던 싸이는 시청 앞 거리응원에 나갔다가 방송 리포터와 인터뷰한 일을 계기로 정지가 풀렸고, 이 곡이 담긴 3집으로 복귀에 성공했다.',
  usage_note = '회식, 체육대회, 응원전처럼 여럿이 함께 달아오르는 자리에서 분위기를 띄우는 노래로 틀거나 인용할 때 어울린다. ''오늘 텐션 챔피언급''처럼 가볍게 신남을 표현하는 말로도 쓴다.',
  caution = '원곡의 시끌벅적한 응원 분위기를 전제로 한 표현이라 조용한 회의나 애도의 자리에서 쓰면 어색하다. 2002년 월드컵 세대의 향수가 담겨 있어 어린 세대에게는 맥락이 통하지 않을 수 있으니, 곡명을 함께 밝히는 편이 안전하다.',
  usage_examples = '[{"situation":"회식 단톡방","text":"오늘 마무리는 챔피언 틀고 다 같이 뛰자ㅋㅋ"},{"situation":"SNS 댓글","text":"이 응원 텐션 완전 챔피언급이다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'jjuvahfy'
  and slug = '싸이---챔피언'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

