-- 그래 결심했어 (v2kq6jp9 / 그래-결심했어)
update public.memes set
  description = 'MBC ''일요일 일요일 밤에''의 코너 ''인생극장''에서 이휘재가 두 갈래 선택지 앞에서 마음을 정하며 외치던 대사다. 인생극장은 사소한 상황에서 주인공이 어느 쪽을 고르느냐에 따라 전혀 다른 결말이 이어지는 형식의 코미디로, 영화 ''슬라이딩 도어즈''를 떠올리게 하는 구성이었다. 대표 장면은 수영장 안전요원이던 이휘재가 물소리를 듣고 나가 볼지 망설이다 ''그래, 결심했어!''를 외치며 달려가는 모습이며, 주먹을 쥐었다 내리며 외치는 동작이 함께 기억된다. 지금은 점심 메뉴를 고르는 일부터 이직이나 결혼 같은 큰 결정까지, 고민 끝에 마음을 정한 순간을 장난스럽게 알릴 때 쓴다.',
  origin = '1994년 방송된 MBC ''일요일 일요일 밤에''의 ''인생극장'' 코너에서 나왔다. OSEN은 이 코너가 1993~1994년 이휘재를 전국적인 스타로 만들었다고 소개하며, 결정의 순간 주먹을 쥐고 외치는 이 대사가 다음 전개에 대한 시청자의 기대를 키웠다고 전한다.',
  usage_note = '메뉴 고르기, 여행지 정하기, 구매 버튼 누르기처럼 망설이던 일에 결론을 냈을 때 장난스럽게 선언하는 말로 어울린다. 선택지 두 개를 나란히 보여 준 뒤 이 대사를 붙이면 원래 코너의 맛이 산다.',
  caution = '진지하게 고민하는 사람에게 결정을 재촉하며 쓰면 놀리는 말처럼 들릴 수 있다. 큰 결정에 이 말을 붙일 때는 상대가 가볍게 받아들일 분위기인지 먼저 살피는 것이 좋다.',
  usage_examples = '[{"situation":"친구들과 저녁 메뉴 정하는 단톡방","text":"치킨이냐 피자냐 고민하다가… 그래, 결심했어! 치킨이다"},{"situation":"SNS 구매 인증 캡션","text":"장바구니에 3주 묵혀 둔 거 오늘 결제했다. 그래, 결심했어!"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'v2kq6jp9'
  and slug = '그래-결심했어'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

