-- 차인표 짤 (vxb8bxb5 / 차인표-짤)
update public.memes set
  description = '1994년 MBC 드라마 ''사랑을 그대 품안에''에서 차인표가 윙크와 함께 검지를 까딱이던 동작을 가리키는 짤이다. 극 중 차인표는 오토바이를 타고 색소폰을 부는 부유하고 외로운 청년이었고, 이 손가락 동작은 여성을 사로잡는 멋 부린 몸짓으로 그려졌다. YTN은 이 장면의 손가락 동작만으로도 그가 전국적인 인기를 얻었다고 전한다. 방송이 끝난 뒤 신동엽이 예능에서 가죽 재킷을 입고 이 동작을 패러디하면서 더 널리 퍼졌다고 차인표가 직접 말한 적도 있다. 지금은 느끼하게 자신감을 부리거나 과장되게 멋을 낼 때, 또는 상대를 장난스럽게 놀릴 때 이 짤을 리액션으로 붙인다.',
  origin = '1994년 방영된 MBC ''사랑을 그대 품안에''의 장면이 출발점이다. 서울신문은 방영 중이던 1994년 7월 차인표를 이 드라마 한 편으로 하루아침에 스타가 된 신인으로 소개했다. 차인표는 2023년 방송에서 이 동작에 특별한 의도가 없었고 유행할 줄도 몰랐다고 말했다.',
  usage_note = '친구가 과하게 멋을 부리거나 느끼한 말을 던졌을 때, 가볍게 받아치는 리액션 짤로 어울린다. 90년대 드라마를 추억하는 대화나 패러디 영상에도 자주 쓴다.',
  caution = '차인표 본인이 이 작품의 이미지를 벗고 싶다고 밝힌 적이 있어, 외모나 연기를 비하하는 조롱의 의도로 쓰면 실례가 될 수 있다. 특정인의 외모나 말투를 놀리는 용도로 붙이면 상대가 기분 나빠할 수 있다.',
  usage_examples = '[{"situation":"친구 단톡방","text":"야 방금 그 윙크 뭐냐ㅋㅋ 차인표 짤 그대로네"},{"situation":"SNS 댓글","text":"자신감 넘치는 손가락 흔들기… 이건 90년대 차인표 감성이다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'vxb8bxb5'
  and slug = '차인표-짤'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

