-- 조성모 - 아시나요 (sx46pp6f / 조성모---아시나요)
update public.memes set
  description = '2000년 조성모가 발표한 3집 ''아시나요''는 노래만큼이나 대형 뮤직비디오로 화제가 된 곡이다. 베트남전쟁을 배경으로 한 군인과 현지 여성의 비극적인 사랑을 영화처럼 그려, 제작비가 약 10억 원에 이른다고 보도됐다. 뮤직비디오는 8월 29일 먼저 공개돼 앨범 CD와 묶어 팔렸고, 앨범은 9월 1일 발매돼 집계상 200만 장 이상 팔렸다. 같은 해 엠넷 시상식에서는 ''아시나요''가 뮤직비디오 부문 상을 받았다. 지금은 영화 같은 스케일의 뮤직비디오, 곧 2000년대 초 드라마타이즈 뮤비 전성기를 이야기할 때 대표 사례로 언급된다.',
  origin = '뮤직비디오는 2000년 8월 29일 공개됐고, 3집 앨범은 같은 해 9월 1일 나왔다. 영상 속 백마부대 휘장 노출과 부대가 전멸하는 설정을 두고 참전 단체와 군이 반발했고, 소속사는 휘장만 지우고 내용은 고치지 않겠다고 해 논란이 이어졌다.',
  usage_note = '영화 같은 영상미나 큰 규모로 만든 뮤직비디오를 칭찬하거나, 2000년대 초 대형 뮤비 시절을 추억할 때 어울린다. 곡 제목은 ''아시나요''지만 ''이 뮤비 아시나요급 스케일''처럼 규모를 빗댄 표현으로도 쓴다.',
  caution = '베트남전쟁을 소재로 한 작품이라 전쟁과 참전 경험을 가볍게 소비하는 농담으로 번지면 당시 논란이 됐던 지점을 건드릴 수 있다. 출연진이나 수상 내역 같은 세부 사실은 기억에 의존해 단정하지 않는 편이 안전하다.',
  usage_examples = '[{"situation":"추억의 노래 모임 단톡방","text":"그때 아시나요 뮤비 제작비 엄청났다던데, 지금 봐도 영화 같다"},{"situation":"유튜브 댓글","text":"2000년에 이런 스케일 뮤비를 만들었다니… 아시나요는 진짜 레전드다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'sx46pp6f'
  and slug = '조성모---아시나요'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

