-- 요아정 (uhe6h8eu / 요아정)
update public.memes set
  description = '요아정은 요거트 아이스크림 프랜차이즈 ''요거트아이스크림의정석''의 줄임말로, 2024년 SNS를 타고 10~20대 사이에서 크게 유행한 디저트 브랜드와 그 먹는 방식을 가리킨다. 아이스크림 위에 생과일, 과자, 꿀 스틱, 소스 같은 토핑을 직접 골라 올리는 방식이어서, 사람마다 자신만의 조합을 만들어 인스타그램 등에 공유하는 ''요아정 꿀조합'' 게시물이 밈처럼 퍼졌다. 가수와 유튜버 등 유명인이 자기 조합을 소개하면 팬들이 그대로 따라 주문하는 흐름도 생겼다. 언론은 탕후루의 인기가 식은 뒤 이 자리를 이은 디저트로 소개했고, 매장 수도 2024년 안에 크게 늘었다.',
  origin = '요거트아이스크림의정석은 2021년 1호점을 열었고, 2024년 6월 기사 기준 전국 298개, 같은 해 9월 기사 기준 약 470개 매장으로 늘었다. 유명인이 SNS에 자기 토핑 조합을 올리면 팬들이 따라 하는 방식으로 유행이 번졌다.',
  usage_note = '디저트 얘기를 하거나 자기만의 토핑 조합을 자랑할 때, 또는 ''오늘은 요아정 가는 날'' 같은 약속 문구로 가볍게 쓴다. 조합 이름을 붙여 공유하면 원래 유행의 방식과 맞는다.',
  caution = '특정 프랜차이즈의 상호를 줄인 말이라 광고나 협찬 글처럼 보일 수 있으니, 후기를 올릴 때 협찬 여부를 분명히 하는 편이 좋다. 유행하는 디저트 이름은 시간이 지나면 금방 낡은 말이 될 수 있어 오래된 글에서는 어색해질 수 있다.',
  usage_examples = '[{"situation":"친구와 약속 잡는 단톡방","text":"시험 끝났으니까 오늘은 요아정 가서 꿀조합으로 달리자"},{"situation":"인스타그램 캡션","text":"내 인생 요아정 조합 공개. 딸기랑 꿀 스틱은 진짜 무조건이다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'uhe6h8eu'
  and slug = '요아정'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

