-- 박세리 맨발 투혼 (46x2hg97 / 박세리-맨발-투혼)
update public.memes set
  description = '1998년 7월 7일 US여자오픈 연장전에서 박세리가 신발과 양말을 벗고 물에 들어가 공을 쳐낸 장면을 가리킨다. 당시 한국은 IMF 외환위기로 움츠러든 때여서, 연못 가장자리 경사진 러프에 빠진 어려운 공을 포기하지 않고 쳐낸 이 모습이 국민에게 용기와 희망의 상징이 됐다. 이 샷은 연장 18번홀에서 나왔고, 박세리는 서든데스 두 번째 홀에서 버디를 잡아 우승했다. 서울신문은 사설에서 물속에 들어간 하얀 발과 검게 그은 종아리의 대비를 들어 그의 의지가 혹독한 자기 단련의 결과임을 말했다. 지금은 어려운 상황에서도 끝까지 포기하지 않는 모습을 가리켜 ''맨발 투혼''이라는 말로 쓴다.',
  origin = '1998년 7월 7일 US여자오픈에서 박세리는 태국의 아마추어 제니 추아시리폰과 92홀 접전을 벌여 우승했다. 연장 18번홀에서 티샷이 연못 옆 경사진 러프에 빠지자 신발과 양말을 벗고 물에 들어가 공을 쳤다. 박세리는 경기 전부터 경제 위기에 빠진 나라에 희망을 주고 싶다고 말했다고 스포츠경향은 전한다.',
  usage_note = '어려운 환경에서도 포기하지 않고 끝까지 해낸 노력이나 응원을 표현할 때 어울린다. 스포츠 명장면을 회고하거나 IMF 시절의 기억을 이야기할 때도 상징적으로 인용한다.',
  caution = '국가적 위기와 결부된 감동 서사라, 일상의 사소한 노력에 과장해서 붙이면 가볍게 들릴 수 있다. 힘든 사람에게 ''투혼''을 요구하는 말처럼 쓰면 불쾌할 수 있으니 상대의 상황을 살펴야 한다.',
  usage_examples = '[{"situation":"직장 메신저","text":"밤새 장애 복구한 팀원들 보니까 완전 박세리 맨발 투혼이다. 다들 고생했어요"},{"situation":"스포츠 커뮤니티 댓글","text":"연못에 들어가던 그 장면은 지금 봐도 소름이다. 맨발 투혼이란 말이 딱이다"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '46x2hg97'
  and slug = '박세리-맨발-투혼'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

