-- 한 뚝배기 하실래예 (facgycuz / 한-뚝배기-하실래예)
update public.memes set
  description = '2009년 농심 둥지쌀국수 뚝배기 광고에서 외국 출신 방송인 하일(로버트 할리)이 구수한 경상도 사투리로 "한 뚝배기 하실래예?"라고 권하며 광고를 마무리하는 대사다. 뚝배기에 담긴 쌀국수를 먹는 서양인이 부산 사투리를 능청스럽게 구사하는 모습이 웃음 포인트였고, 마지막 한마디가 유독 중독성이 강하다는 평을 받았다. 광고가 알려진 뒤 이 대사를 따라 하는 패러디 영상이 수없이 만들어졌고, 이후 농심이 쌀국수짬뽕 광고에도 하일을 기용하면서 "쌀짬뽕 하실래예" 같은 변형 영상이 화제가 됐다는 보도가 있다. 제품 자체보다 말투와 억양이 기억에 남은 광고 유행어의 사례로 볼 수 있다.',
  origin = '농심이 2009년 10월께 방영한 15초짜리 둥지쌀국수 뚝배기 TV 광고에서 하일이 이 대사를 했다. 한국학중앙연구원 교육용 위키는 방영일을 2009년 10월 4일로 적고 있고, 2011년 기사는 이 말이 수많은 패러디를 낳으며 유행어가 됐다고 전한다.',
  usage_note = '상대에게 무언가를 같이 하자고 권할 때 경상도 억양을 흉내 내어 "한 ○○ 하실래예" 꼴로 장난스럽게 바꿔 쓰면 잘 어울린다. 음식 이야기에서 특히 자연스럽다.',
  caution = '사투리 억양을 과장해 흉내 내면 특정 지역 말투를 놀리는 것처럼 들릴 수 있으니 친한 사이의 가벼운 농담에서만 쓰는 편이 좋다. 2009년 광고 대사라 어린 세대는 출처를 모를 수 있어 설명이 필요하다.',
  usage_examples = '[{"situation":"단톡방에서 점심 메뉴를 정할 때","text":"오늘 점심은 국물 땡기는데, 한 뚝배기 하실래예?"},{"situation":"SNS 캡션, 뚝배기 라면 사진과 함께","text":"퇴근길 야식으로 한 뚝배기 했다 ㅋㅋ 같이 하실래예?"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'facgycuz'
  and slug = '한-뚝배기-하실래예'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

