-- 사쿠란보 챌린지 (m8nj7cm6 / 사쿠란보-챌린지)
update public.memes set
  description = '일본 가수 오오츠카 아이가 2003년에 낸 노래 ''사쿠란보(さくらんぼ)''에 맞춰 춤을 추거나 반응하는 영상 유행을 가리킨다. 2000년대 초 블로그 배경음악으로도 쓰이며 한국에서 이미 익숙했던 곡인데, 2020년 아프리카TV 같은 인터넷 방송에서 BJ들이 노래에 맞춰 춤추는 ''사쿠란보 리액션''이 퍼지면서 다시 주목받았다. 이후 가수들의 커버 영상과 틱톡 영상으로 번졌고, 2020년 12월에는 유튜브 뮤직 한국 차트 10위권에 들었다고 일본 매체가 전했다. 귀엽고 어색한 동작을 일부러 크게 따라 하는 것이 재미 포인트라, 옛날 노래를 가볍게 리메이크하는 레트로 유행의 한 예로 자주 언급된다.',
  origin = '원곡은 2003년 발매됐다. 일본 매체는 2017년 일본 개그 콤비의 만담에 쓰인 뒤 2018년 배우 이정석의 틱톡 따라 하기, 2019년 김준수의 커버가 이어졌고 2020년 아프리카TV로 번졌다고 정리한다. 위키트리도 김준수의 커버와 일본 콘서트 무대가 입소문을 타 2020년 인터넷 방송으로 확산됐다고 전한다.',
  usage_note = '옛날 노래를 새삼 다시 틀어 놓고 귀엽게 춤추는 영상이나 스트리머 리액션 장면을 이야기할 때 쓰면 잘 맞는다. 추억의 노래를 챌린지로 다시 즐기는 분위기를 설명할 때도 어울린다.',
  caution = '일본 노래의 유행이라 원곡과 가사를 둘러싼 저작권이나 커버 영상의 사용 허락을 따져 보지 않고 상업적 영상에 쓰면 문제가 될 수 있다. 또 유행의 시작점이 한 사람이나 한 방송이라고 단정하면 틀리기 쉬워, 여러 경로가 겹친 유행으로 설명하는 편이 정확하다.',
  usage_examples = '[{"situation":"단톡방에서 옛날 노래 얘기를 하다가","text":"사쿠란보 챌린지 영상 봤어? 이 노래 싸이월드 시절 감성 그대로라 계속 돌려 본다"},{"situation":"SNS 캡션, 친구들과 춤 영상을 올리며","text":"퇴근하고 친구들이랑 사쿠란보 챌린지 도전했는데 박자가 하나도 안 맞음 ㅋㅋ"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'm8nj7cm6'
  and slug = '사쿠란보-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

