-- Into the Arena (nreumpyz / Into-the-Arena)
update public.memes set
  description = '「Into the Arena」는 가수 신해철이 2002 한일 월드컵을 앞두고 붉은악마의 요청을 받아 만든 응원곡이다. 월드컵 공식 응원 음반(영문 표기 Dream Come True)의 1번 트랙으로 실렸고, 같은 음반에는 윤도현밴드의 「오 필승 코리아」도 들어 있다. 이 곡이 응원 문화와 함께 자주 언급되는 이유 중 하나는 "대~한민국" 구호 때문이다. 2014년 보도에 따르면 신해철의 소속사는 이 구호를 처음 음원으로 만든 사람이 신해철이며 그 저작권도 갖고 있다고 밝혔다. 그래서 월드컵 시즌마다 응원가 목록과 2002년 추억을 이야기할 때 함께 불려 나오는 곡이다.',
  origin = '텐아시아는 신해철이 2002년 붉은악마의 요청으로 이 곡을 작곡해 월드컵 공식 응원 음반 1번 트랙에 실었다고 전한다. 코리아타임스도 2002년 음반 Dream Come True에 신해철이 부른 이 곡이 실려 있다고 적는다.',
  usage_note = '월드컵이나 국가대표 경기 시즌에 응원가 목록을 이야기하거나 2002년 응원 문화를 추억할 때 언급하면 자연스럽다. 신해철의 곡 가운데 스포츠 응원용으로 만든 곡을 소개할 때도 쓸 수 있다.',
  caution = '"대~한민국" 구호 음원은 아무나 써도 되는 공용 음원으로 오해되기 쉽지만, 2014년 보도에서 소속사는 비영리 사용만 열려 있다고 설명했다. 영상 배경음악이나 상업 용도로 쓰기 전에는 권리 관계를 따로 확인해야 한다. 또 2002년 응원가의 대표곡으로 흔히 꼽히는 「오 필승 코리아」와 혼동하지 않는 것이 좋다.',
  usage_examples = '[{"situation":"단톡방에서 월드컵 응원 플레이리스트를 짜며","text":"응원 플리 첫 곡은 신해철 Into the Arena로 가자, 2002 공식 응원 음반 1번 트랙이래"},{"situation":"유튜브 댓글, 2002 월드컵 영상 아래","text":"그때 붉은악마 요청으로 신해철이 만든 곡이 이거였다는 거 아는 사람 있나요?"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'nreumpyz'
  and slug = 'Into-the-Arena'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

