-- SS501 U R Man 암욜맨 (g9jsxkfb / SS501-U-R-Man-암욜맨)
update public.memes set
  description = 'SS501의 「U R Man」은 2008년 11월 발매된 미니앨범의 타이틀곡으로, 멤버 세 명이 참여한 곡이다. ''암욜맨''은 이 곡의 별명인데, 후렴 발음이 그렇게 들려 붙은 이름이다. 실제 제목은 U R Man이라서 ''암욜맨''으로 검색했다가 결과가 이상해 당황한 사람이 많았다는 기사가 2015년에 나왔다. 한 번 들으면 후렴이 머릿속을 떠나지 않는다는 평 때문에 시험 기간에 들으면 안 되는 노래로 불렸고, 2019년 기사는 이 곡을 수능 금지곡 목록 1위에 올렸다. 그래서 노래 자체보다 중독성 있는 후렴과 별명으로 더 자주 회자된다.',
  origin = '2008년 11월 21일 DSP미디어에서 발매한 앨범 U R Man의 타이틀곡이다. 별명 ''암욜맨''은 후렴 발음에서 나왔다고 iMBC연예가 2015년에 소개했고, 위키트리는 2019년 수능 금지곡 8선에서 이 곡을 1위로 꼽았다.',
  usage_note = '중독성 있는 후렴이 계속 맴돌 때나 수능, 시험 기간에 듣지 말아야 할 노래를 꼽을 때 쓰면 맞다. 2000년대 후반 아이돌 노래를 추억하는 대화에서도 자연스럽다.',
  caution = '수능 금지곡은 "듣기만 하면 집중이 깨진다"는 식의 농담이지 공식 지정이 아니므로, 실제 수험생에게 일부러 틀어 주거나 놀리는 용도로 쓰면 곤란할 수 있다. 또 곡을 SS501 전체가 부른 것으로 단정하기보다 세 명이 참여한 곡이라고 적는 편이 정확하다.',
  usage_examples = '[{"situation":"단톡방에서 시험 기간 이야기를 하다가","text":"시험 기간에 암욜맨 들으면 후렴이 계속 맴돌아서 공부 못 한다 ㅋㅋ"},{"situation":"유튜브 댓글, 2008년 무대 영상 아래","text":"암욜맨은 제목이 U R Man인 줄 몰라서 검색 못 하던 시절이 있었지"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'g9jsxkfb'
  and slug = 'SS501-U-R-Man-암욜맨'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

