-- 정주영 소떼 방북 (m266mu7d / 정주영-소떼-방북)
update public.memes set
  description = '1998년 현대그룹 정주영 명예회장이 소 떼를 이끌고 판문점을 거쳐 북한으로 간 사건이다. 1차는 6월 16일에 소 500마리를 트럭 50대에 싣고 임진각을 출발해 판문점을 넘었고, 2차는 같은 해 10월에 소 501마리를 보내 두 차례 합쳐 1,001마리가 됐다. 정 회장은 군사분계선을 걸어서 넘었고, 이 장면은 CNN에 생중계되며 외신이 휴전선이 열렸다고 보도할 만큼 큰 화제가 됐다. 분단 이후 민간 합의로 판문점을 통해 민간인이 북한에 들어간 첫 사례로 평가되며, 이후 금강산 관광과 2000년 남북정상회담, 개성공단으로 이어지는 계기가 됐다. 오늘날에는 규모가 크거나 판을 뒤흔드는 결단을 소떼 방북에 빗대어 말하는 표현으로도 쓰인다.',
  origin = '한국민족문화대백과는 1차 방북을 1998년 6월 16일, 2차를 같은 해 10월로 기록하고 총 1,001마리를 보냈다고 설명한다. 뉴시스는 정 회장이 젊은 시절 아버지가 소를 판 돈으로 사업을 시작한 빚을 갚는 뜻이라고 이 방북을 설명했다고 전한다.',
  usage_note = '통 큰 결단이나 파격적인 이벤트, 남들이 엄두 못 낸 일을 밀어붙인 사례를 비유할 때 쓰면 잘 맞는다. 남북 교류사나 정주영 회장의 일화를 소개하는 글에서 사건 자체를 가리킬 때도 쓸 수 있다.',
  caution = '실제 역사적 사건이고 남북관계와 대북 정책을 둘러싼 평가가 사람마다 크게 다르므로, 가벼운 농담이나 조롱에 끌어다 쓰면 불쾌하게 받아들이는 사람이 있을 수 있다. 소의 마릿수와 방북 시점을 말할 때는 1차 500마리, 2차 501마리로 나눠 정확히 말하는 것이 좋다.',
  usage_examples = '[{"situation":"직장 메신저에서 사장님의 파격적인 투자 결정을 두고","text":"이번 결단은 정주영 소떼 방북급 스케일이네요."},{"situation":"SNS 댓글, 대규모 이벤트 소식 아래","text":"이 정도면 소떼 방북 이후 가장 큰 판 벌이는 거 아닌가요"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'm266mu7d'
  and slug = '정주영-소떼-방북'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

