-- 팝캣 (jajqn55r / 팝캣)
update public.memes set
  description = '입을 "O" 모양으로 크게 벌린 고양이 사진과 입을 다문 사진을 번갈아 보여 주면 고양이가 노래하거나 소리를 내는 것처럼 보이는 밈이다. 고양이 이름은 오트밀이고, 벌레를 보며 짹짹거리는 영상을 주인이 2020년 10월에 올린 것이 시작이었다. 인스타그램에서 이 짤을 노래에 맞춰 입을 벌리는 뮤직비디오 식으로 편집하면서 인기를 끌었다. 같은 해 12월에는 영국 셰필드대 학생 세 명이 고양이를 클릭할 때마다 팝 소리가 나고 국가별 클릭 수를 겨루는 popcat.click 사이트를 만들었다. 2021년 8월에는 대만, 태국, 말레이시아 이용자들이 순위 경쟁에 열을 올려 화제가 됐고, 자동 클릭 프로그램을 막지 않는다는 점도 지적됐다.',
  origin = '위키백과는 트위터 이용자 Xavier BFB가 2020년 10월 중순 오트밀이 벌레를 향해 짹짹거리는 영상을 디스코드에 올린 것이 시작이라고 설명한다. 게임 popcat.click은 2020년 12월 11일 공개됐고, 말레이시아 매체 Rojak Daily도 같은 경위를 전한다.',
  usage_note = '단순한 동작이 반복되며 묘하게 중독적인 짤이나, 별것 아닌 클릭 경쟁에 몰입하는 상황을 말할 때 쓰기 좋다. 귀여운 동물 영상 이야기에 곁들이기에도 무난하다.',
  caution = '특정 국가나 이용자들의 경쟁을 비하하거나 자동 클릭 프로그램으로 순위를 조작하는 방식을 부추기는 맥락에서 쓰면 곤란하다. 또 같은 이름의 밈 코인이나 투자 상품과 혼동해 투자 추천처럼 들리지 않도록 주의해야 한다.',
  usage_examples = '[{"situation":"단톡방에서 심심할 때","text":"팝캣 클릭하다 보니 어느새 십 분 지났다 ㅋㅋ 이거 끊기 힘들다"},{"situation":"SNS 댓글, 고양이 영상 아래","text":"입 벌린 모양 보니까 팝캣 생각난다 ㅋㅋㅋ"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'jajqn55r'
  and slug = '팝캣'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

