-- 푸바오 (j75ahdbj / 푸바오)
update public.memes set
  description = '푸바오는 2020년 7월 20일 에버랜드 판다월드에서 아이바오와 러바오 사이에 태어난 자이언트 판다의 이름이다. 국내에서 자연 번식으로 태어난 첫 대왕판다였고, 사육사들과 지내며 행복해하는 모습이 영상으로 퍼지면서 큰 인기를 얻었다. 이름은 팬 투표로 정해졌으며 ''행복을 주는 보물''이라는 뜻이다. 팬들은 ''푸공주'', ''푸뚠뚠'' 같은 애칭으로 불렀다. 2024년 4월 중국으로 돌아간 뒤에도 이름 자체가 귀여운 동물, 이별의 아쉬움, 팬덤 문화를 가리키는 말로 쓰이고, 사육사 강철원 씨가 남긴 ''할부지의 영원한 아기 판다'' 같은 말과 함께 회자된다.',
  origin = '2020년 7월 20일 용인 에버랜드 판다월드에서 태어났고, 2021년 1월 일반에 공개된 뒤 약 1155일 동안 판다월드 방문객이 550만 명에 이르렀다는 집계가 있다. 멸종위기종 보전 협약에 따라 만 4세가 되기 전에 중국으로 돌아가야 했고, 2024년 4월 3일 사육사와 함께 중국 쓰촨성으로 떠났다.',
  usage_note = '귀엽고 통통한 동물 영상에 감탄할 때, 또는 판다와 사육사 이야기처럼 따뜻한 팬덤 화제를 언급할 때 어울린다. 판다 영상 댓글이나 에버랜드 방문 후기에서 이름만 불러도 맥락이 통한다.',
  caution = '푸바오는 실제 살아 있는 동물이고 반환을 아쉬워한 팬이 많아서, 이별이나 중국에서의 생활을 비꼬는 농담은 불쾌감을 줄 수 있다. 현재 상태에 대한 확인되지 않은 소문을 사실처럼 퍼뜨리는 것도 피하는 편이 좋다.',
  usage_examples = '[{"situation":"단톡방에서 판다 영상을 공유하며","text":"푸바오 대나무 먹는 영상 또 봤는데 볼 때마다 귀여워서 힘이 빠진다 ㅋㅋ"},{"situation":"에버랜드 방문 후기 댓글","text":"판다월드 가니까 푸바오 생각나서 괜히 울컥했어요"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'j75ahdbj'
  and slug = '푸바오'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

