-- 히밥 (ckzrrca9 / 히밥)
update public.memes set
  description = '히밥은 대식가 먹방으로 알려진 크리에이터의 이름이자, 그의 먹방 방식과 발언이 함께 회자되는 표현이다. 아프리카TV에서 신입 BJ로 소개되던 시절부터 짧은 시간에 엄청난 양을 먹는 도전 먹방으로 눈길을 끌었고, 이후 유튜브 먹방 채널로 이름을 알렸다. 가장 높은 조회수를 낸 콘텐츠는 구독자가 보낸 배달 음식을 7~8시간 동안 모두 먹는 ''음식 랜덤 디펜스''였고, 조회수는 800만~900만 회에 이른다. 본인은 떡볶이, 라면, 마라탕처럼 누구나 아는 맛의 빨간 음식이라는 점을 조회수가 잘 나온 이유로 꼽았다.',
  origin = '2020년 2월 인사이트가 아프리카TV 먹방 BJ로서 ''대왕 돈가스''를 20분 제한 중 7분 45초 만에 먹은 신입이라고 소개했다. 정확한 데뷔 시점은 열어 본 출처에서 확인되지 않는다. 이후 유튜브 채널로 활동을 넓혔고 2025년 7월 기사 기준 구독자는 169만 명이다.',
  usage_note = '엄청난 양을 먹거나 먹는 속도가 빠른 사람을 가리킬 때, 먹방 콘텐츠의 인기 요인을 이야기할 때 어울린다. 뷔페나 대량 주문 자리에서 가볍게 감탄하는 말로 쓰기 좋다.',
  caution = '특정 실존 인물의 이름이라 외모나 식사량, 체형을 놀리는 말투로 쓰면 무례해질 수 있다. 친구나 동료에게 ''히밥이냐''라고 할 때도 상대가 식사량 얘기를 불편해하지 않는지 살피는 것이 좋다.',
  usage_examples = '[{"situation":"단톡방에서 대량 주문을 하며","text":"오늘 치킨 세 마리 시켰는데 이 정도면 히밥 따라가는 거 아니냐 ㅋㅋ"},{"situation":"유튜브 댓글에서 먹방 영상을 보고","text":"역시 빨간 음식이 조회수 잘 나온다더니 히밥 말이 맞았네"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'ckzrrca9'
  and slug = '히밥'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

