-- 런닝맨 초능력자 특집 (u5w3wz3t / 런닝맨-초능력자-특집)
update public.memes set
  description = '런닝맨 초능력자 특집은 출연자 일곱 명에게 각기 다른 초능력을 주고 서로 겨루게 한 SBS 런닝맨의 크리스마스 특집을 가리킨다. 유재석은 공간 지배자, 하하는 시간 지배자, 지석진은 불사조, 이광수는 데스노트처럼 게임의 판도를 흔드는 능력을 받았고, 분신과 예지 같은 능력도 등장했다. 특집은 ''제2대 최강자''를 가리는 대결로 끝났다. 제작진이 여러 차례 최고의 특집으로 꼽을 만큼 호응을 얻었고, 이후에도 비슷한 능력 설정의 레이스가 다시 만들어져 런닝맨 게임 포맷의 대표적인 갈래로 자리 잡았다.',
  origin = '2011년 12월 25일 SBS 런닝맨 74회 ''메리메리 크리스마스 특집''으로 방송됐다. 위키백과의 회차 목록에 따르면 같은 해 12월 12일 고양 킨텍스에서 촬영됐고 게스트 없이 멤버끼리 대결했으며 개리가 우승해 유럽 여행권을 받았다. 이후 196회와 509회에서 비슷한 능력 레이스가 이어졌다.',
  usage_note = '한 사람의 특수한 능력이나 규칙 때문에 판이 뒤집히는 게임, 예능 얘기를 할 때 어울린다. 런닝맨 팬끼리 명장면이나 최강자전을 회고할 때 회차명으로 쓰기 좋다.',
  caution = '초능력을 소재로 한 런닝맨 회차가 여러 번 있어서 후속 회차와 혼동하기 쉽다. 74회를 가리킨다면 2011년 크리스마스 특집이라고 밝혀야 하며, 방송을 보지 않은 사람에게는 맥락이 전달되지 않는 내부 농담일 수 있다.',
  usage_examples = '[{"situation":"예능 얘기를 하는 단톡방","text":"시간 지배자 하하 나왔던 런닝맨 초능력자 특집 다시 보는데 왜 이렇게 재밌냐"},{"situation":"보드게임 중 특정 카드가 판을 뒤집었을 때","text":"이 카드 하나로 뒤집히네 완전 초능력자 특집이다 ㅋㅋ"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'u5w3wz3t'
  and slug = '런닝맨-초능력자-특집'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

