-- 지민 Like Crazy 챌린지 (g9d78e49 / 지민-Like-Crazy-챌린지)
update public.memes set
  description = '지민 Like Crazy 챌린지는 방탄소년단 지민의 첫 솔로 앨범 FACE의 타이틀곡 ''Like Crazy'' 안무 일부를 따라 추는 영상 챌린지다. 지민이 곡의 하이라이트 안무를 짧은 영상으로 공개하면서 시작됐고, 방탄소년단 공식 틱톡 계정에 슈가, 제이홉과 함께 춘 영상이 올라오며 퍼졌다. 한국 팬들 사이에서는 평소 아이돌 챌린지보다 난도가 훨씬 높다는 반응이 나왔고, 비전문가가 따라 하기에는 어렵다는 말이 많았다. 이후 르세라핌 멤버들처럼 다른 K팝 가수들도 같은 안무 영상을 올리며 참여했다. 곡은 빌보드 핫100 1위로 데뷔해 챌린지와 함께 화제가 됐다.',
  origin = '''Like Crazy''는 2023년 3월 24일 지민의 첫 솔로 앨범 FACE로 발매됐다. 발매 직후인 3월 25일 코리아부 보도에 지민의 챌린지 영상 공개가 나오고, 며칠 뒤 방탄소년단 공식 틱톡 계정에 슈가, 제이홉과의 영상이 올라왔다. 곡은 2023년 4월 8일자 빌보드 핫100에서 1위로 데뷔해, 지민이 한국 솔로 아티스트로는 처음 정상에 올랐다.',
  usage_note = 'K팝 솔로 안무 챌린지의 대표 사례를 설명할 때, 또는 어려운 안무에 도전하는 영상을 올릴 때 어울린다. 틱톡이나 릴스 캡션에 곡 이름과 함께 쓰는 식이다.',
  caution = '안무 난도가 높아 무리하게 따라 하다 다칠 수 있으니 준비운동 없이 흉내 내는 것은 권하지 않는다. 팬덤이 큰 가수라 안무를 비하하거나 다른 가수와 비교하며 깎아내리는 말은 논쟁으로 번지기 쉽다.',
  usage_examples = '[{"situation":"틱톡 영상 캡션","text":"Like Crazy 챌린지 도전했는데 하이라이트 구간부터 이미 숨참 ㅋㅋ"},{"situation":"댄스 동아리 단톡방","text":"이번 주 연습은 지민 Like Crazy 챌린지 안무 한 구간씩 쪼개서 해보자"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'g9d78e49'
  and slug = '지민-Like-Crazy-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

