-- ITZY Wannabe 챌린지 (369e5dtd / ITZY-Wannabe-챌린지)
update public.memes set
  description = 'ITZY Wannabe 챌린지는 2020년 3월 있지가 신곡 ''WANNABE''를 내놓으며 틱톡에서 연 해시태그 챌린지(#WANNABEITZY)다. 곡이 자기 자신을 있는 그대로 받아들이는 메시지를 담고 있어서, 참가자들은 자신만의 색깔과 정체성을 당당하게 보여 주는 영상을 올리는 방식으로 참여했다. 곡의 안무 가운데 어깨를 흔드는 동작이 포인트 안무로 알려져, 이를 따라 하는 영상도 함께 퍼졌다. 챌린지는 3월 16일까지 진행될 예정이었고, 공식 계정에 올라온 영상은 공개 하루가 안 되어 약 43만 회 조회됐다.',
  origin = '2020년 3월 9일 있지의 EP It''z Me 타이틀곡 ''WANNABE''가 발매될 때 틱톡이 공식 계정을 통한 #WANNABEITZY 챌린지를 시작했다. 틱톡 뉴스룸에 따르면 공식 영상은 게시 하루도 안 되어 약 43만 회 조회됐다. 안무는 이정리 안무가가 맡은 것으로 소개된다.',
  usage_note = '자신감 있는 태도나 개성을 드러내는 영상, 어깨를 쓰는 포인트 안무를 따라 하는 영상에 어울린다. 댄스 챌린지나 개인기 영상을 올릴 때 해시태그와 함께 쓰는 식이다.',
  caution = '챌린지의 취지는 자기다움을 보여 주는 것이어서, 남의 외모나 개성을 놀리는 패러디로 쓰면 원래 뜻과 어긋나 불쾌감을 줄 수 있다. 안무를 흉내 내다 어깨나 목을 다치지 않도록 무리하지 않는 것이 좋다.',
  usage_examples = '[{"situation":"틱톡 영상 캡션","text":"나만의 색깔로 WANNABE 챌린지 도전 #WANNABEITZY"},{"situation":"친구와 연습하며","text":"어깨 동작이 이 곡 포인트래, 박자 맞춰서 한 번 더 해보자"}]'::jsonb,
  content_reviewed_at = '2026-11-20T18:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '369e5dtd'
  and slug = 'ITZY-Wannabe-챌린지'
