-- 무한도전 나비효과 (qz6c5pkw / 무한도전-나비효과)
update public.memes set
  description = '무한도전 나비효과는 MBC 무한도전이 2010년 12월 18일 방송한 환경 소재 특집을 가리킨다. 멤버들이 몰디브 리조트와 얼음 호텔 같은 서로 다른 공간에 머무는 설정인데, 몰디브 쪽에서 에어컨을 켜면 얼음 호텔의 얼음이 녹고, 반대로 얼음 호텔에서 히터를 켜면 그 물이 몰디브 방으로 흘러들어 방이 점점 물에 잠긴다. 일상을 즐기던 각자의 행동이 서로에게 영향을 주는 나비효과 구조라서, 방송은 환경보호에 대한 경각심을 일깨우는 특집으로 평가받았다. 사소한 행동이 돌고 돌아 자신에게 영향을 주는 상황을 이 특집에 빗대 말하기도 한다.',
  origin = '2010년 12월 18일 MBC 무한도전 228회(DVD 순서 기준)로 방송된 ''나비효과 특집''이다. 2016년 iMBC 기사가 무한도전 속 대표적인 나비효과 특집의 하나로 다시 소개했다.',
  usage_note = '내가 한 편한 행동이 결국 나에게 불편함으로 돌아오는 상황, 또는 환경 문제의 연결 구조를 설명할 때 어울린다. 무한도전 명장면을 회고하는 대화에서도 회차명으로 쓸 수 있다.',
  caution = '방송 내용을 근거로 한 환경 메시지라 실제 기후 문제를 가벼운 개그로만 소비하면 취지가 흐려질 수 있다. 방송 설정의 세부 내용은 기억에 의존하지 말고 회차를 확인한 뒤 말하는 편이 안전하다.',
  usage_examples = '[{"situation":"여름철 에어컨 이야기를 하는 단톡방","text":"에어컨 계속 틀다가 전기요금 폭탄이네, 이거 완전 무한도전 나비효과다"},{"situation":"무한도전 회고 게시글 댓글","text":"몰디브에서 에어컨 켜면 얼음 호텔이 녹던 나비효과 편이 아직도 제일 기억에 남음"}]'::jsonb,
